## File 2: `server.js`

```javascript
/**
 * server.js — Main entry point for the Book Management REST API.
 *
 * This file wires together Express, middleware, routes, and error handling.
 * It is intentionally kept thin so that routing logic lives in dedicated files.
 */

const express = require('express');
const bookRoutes = require('./routes/books');

// ---------------------------------------------------------------------------
// 1. Create the Express application instance.
//    Why Express? It provides a minimal, unopinionated framework for building
//    HTTP servers with middleware support, routing, and request/response helpers.
// ---------------------------------------------------------------------------
const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 2. Middleware stack — executed in order for every incoming request.
//
//    a) express.json() parses JSON bodies so req.body is available.
//       Without this, POST/PUT requests with JSON payloads would have an
//       undefined req.body.
//
//    b) Custom logging middleware prints method, path, and timestamp.
//       This is useful for debugging and understanding request flow.
// ---------------------------------------------------------------------------
app.use(express.json());

app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next(); // Pass control to the next middleware/route handler
});

// ---------------------------------------------------------------------------
// 3. Register route modules.
//    Why separate files? Keeping routes in dedicated modules improves
//    readability, testability, and allows different developers to work on
//    different resources without merge conflicts.
// ---------------------------------------------------------------------------
app.use('/books', bookRoutes); // All /books/* routes handled by books.js

// Stats route — kept here since it's a single simple endpoint.
// In a larger app this would also live in its own route file.
app.get('/stats', (req, res) => {
  /**
   * GET /stats
   * Returns aggregate statistics about the book collection.
   *
   * @response {Object} stats
   * @response {number} stats.totalBooks       - Total number of books
   * @response {number} stats.averageRating    - Average rating across all books (0-5)
   * @response {Object} stats.booksByGenre     - Count of books per genre
   * @response {string|null} stats.oldestBook  - Title of the oldest published book
   * @response {string|null} stats.newestBook  - Title of the newest published book
   */

  // Access the in-memory store via the module's exported getter.
  const books = require('./routes/books').getBooks();

  if (books.length === 0) {
    return res.json({
      totalBooks: 0,
      averageRating: 0,
      booksByGenre: {},
      oldestBook: null,
      newestBook: null,
    });
  }

  // Compute statistics using Array methods for clarity.
  const totalBooks = books.length;

  const averageRating = (
    books.reduce((sum, b) => sum + b.rating, 0) / totalBooks
  ).toFixed(2);

  // Group by genre and count occurrences.
  const booksByGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Find oldest and newest by publishedYear.
  const sorted = [...books].sort((a, b) => a.publishedYear - b.publishedYear);
  const oldestBook = sorted[0]?.title ?? null;
  const newestBook = sorted[sorted.length - 1]?.title ?? null;

  res.json({
    totalBooks,
    averageRating: parseFloat(averageRating),
    booksByGenre,
    oldestBook,
    newestBook,
  });
});

// ---------------------------------------------------------------------------
// 4. Global 404 handler — catches requests that don't match any route.
//    Placed AFTER all routes so it only fires for truly unmatched paths.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
  });
});

// ---------------------------------------------------------------------------
// 5. Global error-handling middleware (Express convention: 4 args).
//    This must be the LAST middleware registered.
// ---------------------------------------------------------------------------
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: err.message,
  });
});

// ---------------------------------------------------------------------------
// 6. Start the HTTP server and listen on the configured port.
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`📚 Book Management API running at http://localhost:${PORT}`);
  console.log(`   Try: curl http://localhost:${PORT}/books`);
});
```

