## File 3: `routes/books.js`

```javascript
/**
 * routes/books.js — CRUD route handlers for the /books resource.
 *
 * This module encapsulates all book-related HTTP endpoints and the in-memory
 * data store. Keeping the store inside this module (rather than a global)
 * demonstrates module-level state, a common pattern in small Express apps.
 */

const { Router } = require('express');
const router = Router();

// ===========================================================================
// IN-MEMORY DATA STORE
// ===========================================================================
/**
 * @type {Array<Object>} books
 * In-memory array storing all book records.
 *
 * Why an array? Arrays provide O(1) access by index and are simple to reason
 * about for a demo. For production, you would replace this with a database
 * query layer (e.g., MongoDB, PostgreSQL).
 *
 * Each book object shape:
 * {
 *   id: number,          // Unique identifier (auto-incremented)
 *   title: string,       // Book title
 *   author: string,      // Author name
 *   genre: string,       // Genre/category
 *   publishedYear: number, // Year of publication
 *   rating: number       // Rating from 0.0 to 5.0
 * }
 */
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8,
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7,
  },
];

/** Next auto-incremented ID — simple strategy for demo purposes. */
let nextId = 4;

// Export the getter so server.js can access the store for stats calculations.
module.exports.getBooks = () => books;

// ===========================================================================
// VALIDATION HELPERS
// ===========================================================================

/**
 * Validates that a book payload contains all required fields with correct types.
 *
 * @param {Object} body - The request body to validate.
 * @returns {string|null} Error message if invalid, null if valid.
 */
function validateBookPayload(body) {
  if (!body || typeof body !== 'object') {
    return 'Request body must be a JSON object';
  }
  const required = ['title', 'author', 'genre', 'publishedYear', 'rating'];
  for (const field of required) {
    if (body[field] === undefined || body[field] === null) {
      return `Missing required field: ${field}`;
    }
  }
  if (typeof body.title !== 'string' || body.title.trim() === '') {
    return 'title must be a non-empty string';
  }
  if (typeof body.author !== 'string' || body.author.trim() === '') {
    return 'author must be a non-empty string';
  }
  if (typeof body.genre !== 'string' || body.genre.trim() === '') {
    return 'genre must be a non-empty string';
  }
  if (!Number.isInteger(body.publishedYear)) {
    return 'publishedYear must be an integer';
  }
  const rating = Number(body.rating);
  if (typeof rating !== 'number' || rating < 0 || rating > 5) {
    return 'rating must be a number between 0 and 5';
  }
  return null; // No errors
}

/**
 * Sanitizes input by trimming strings and normalizing types.
 * @param {Object} body - Raw request body.
 * @returns {Object} Cleaned book object ready for storage.
 */
function sanitizeBookInput(body) {
  return {
    title: body.title.trim(),
    author: body.author.trim(),
    genre: body.genre.trim(),
    publishedYear: parseInt(body.publishedYear, 10),
    rating: parseFloat(body.rating),
  };
}

// ===========================================================================
// GET /books — List all books with optional filtering
// ===========================================================================
/**
 * @swagger
 * /books:
 *   get:
 *     summary: Retrieve a list of all books
 *     parameters:
 *       - in: query
 *         name: genre
 *         schema:
 *           type: string
 *         description: Filter by genre (case-insensitive)
 *       - in: query
 *         name: author
 *         schema:
 *           type: string
 *         description: Filter by author name substring
 *       - in: query
 *         name: minRating
 *         schema:
 *           type: number
 *         description: Minimum rating filter (0-5)
 *       - in: query
 *         name: publishedYearAfter
 *         schema:
 *           type: integer
 *         description: Only books published after this year
 *     responses:
 *       200:
 *         description: A list of books
 *         content:
 *           application/json:
 *             schema:
 *               type: array
 *               items:
 *                 $ref: '#/components/schemas/Book'
 */
router.get('/', (req, res) => {
  /**
   * Filtering strategy: apply each query parameter as a filter condition.
   * Using Array.filter() creates a new array without mutating the store.
   * This is a pure function approach — side effects are minimized.
   */
  let result = [...books]; // Copy to avoid mutation

  const { genre, author, minRating, publishedYearAfter } = req.query;

  if (genre) {
    // Case-insensitive genre match
    const normalizedGenre = genre.toLowerCase();
    result = result.filter((b) => b.genre.toLowerCase() === normalizedGenre);
  }

  if (author) {
    // Substring match on author name
    const normalizedAuthor = author.toLowerCase();
    result = result.filter((b) =>
      b.author.toLowerCase().includes(normalizedAuthor)
    );
  }

  if (minRating !== undefined) {
    const min = parseFloat(minRating);
    if (!isNaN(min)) {
      result = result.filter((b) => b.rating >= min);
    }
  }

  if (publishedYearAfter !== undefined) {
    const year = parseInt(publishedYearAfter, 10);
    if (!isNaN(year)) {
      result = result.filter((b) => b.publishedYear > year);
    }
  }

  res.json({
    count: result.length,
    books: result,
  });
});

// ===========================================================================
// GET /books/:id — Get a single book by ID
// ===========================================================================
/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Retrieve a single book by its ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     responses:
 *       200:
 *         description: The book object
 *       404:
 *         description: Book not found
 */
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // isNaN check handles non-numeric IDs like "/abc"
  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid ID format. Must be a number.' });
  }

  // Array.find() returns the first matching element or undefined.
  const book = books.find((b) => b.id === id);

  if (!book) {
    return res.status(404).json({ error: `Book with ID ${id} not found` });
  }

  res.json(book);
});

// ===========================================================================
// POST /books — Create a new book
// ===========================================================================
/**
 * @swagger
 * /books:
 *   post:
 *     summary: Create a new book
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, genre, publishedYear, rating]
 *             properties:
 *               title: { type: string }
 *               author: { type: string }
 *               genre: { type: string }
 *               publishedYear: { type: integer }
 *               rating: { type: number, minimum: 0, maximum: 5 }
 *     responses:
 *       201:
 *         description: The created book (with assigned ID)
 *       400:
 *         description: Validation error
 */
router.post('/', (req, res) => {
  // Validate before creating to fail fast with a clear error message.
  const validationError = validateBookPayload(req.body);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const newBook = {
    id: nextId++, // Auto-increment ID; simple but not safe for distributed systems.
    ...sanitizeBookInput(req.body),
  };

  books.push(newBook);

  // 201 Created is the standard status for resource creation.
  res.status(201).json(newBook);
});

// ===========================================================================
// PUT /books/:id — Full update of an existing book
// ===========================================================================
/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Fully replace a book's data
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, genre, publishedYear, rating]
 *     responses:
 *       200:
 *         description: The updated book
 *       404:
 *         description: Book not found
 *       400:
 *         description: Validation error
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid ID format. Must be a number.' });
  }

  // Find the index so we can replace in-place.
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) {
    return res.status(404).json({ error: `Book with ID ${id} not found` });
  }

  const validationError = validateBookPayload(req.body);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Replace the entire object while preserving the original ID.
  books[index] = {
    id,
    ...sanitizeBookInput(req.body),
  };

  res.json(books[index]);
});

// ===========================================================================
// DELETE /books/:id — Remove a book
// ===========================================================================
/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Delete a book by ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     responses:
 *       200:
 *         description: Confirmation of deletion
 *       404:
 *         description: Book not found
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid ID format. Must be a number.' });
  }

  const index = books.findIndex((b) => b.id === id);
  if (index === -1) {
    return res.status(404).json({ error: `Book with ID ${id} not found` });
  }

  // Remove the book from the array.
  const [deleted] = books.splice(index, 1);

  // 200 OK with the deleted resource is acceptable; some prefer 204 No Content.
  res.json({
    message: `Book "${deleted.title}" has been deleted`,
    deleted,
  });
});

module.exports = router;
```

