## Arquivo 2: `src/models/books.js` — Camada de Dados

```javascript
/**
 * ============================================================
 * CAMADA DE MODELO — Armazenamento em Memória
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ---------------------------------
 * Para fins educacionais, um array em memória é a escolha ideal porque:
 *   1. Elimina a complexidade de configuração de banco de dados.
 *   2. Permite focar nos conceitos de REST, rotas e middleware.
 *   3. O código permanece stateless entre requisições (sem estado persistente).
 *
 * POR QUE UM ARRAY E NÃO UM OBJETO?
 * ---------------------------------
 * Arrays são ideais aqui porque:
 *   - A ordem de inserção é preservada (útil para listagem cronológica).
 *   - Operações como filter(), map() e findIndex() são naturais.
 *   - Para uma API educacional com poucos registros, a performance não é crítica.
 *
 * EM PRODUÇÃO, você substituiria este módulo por um ORM/ODM
 * (como Mongoose para MongoDB ou Sequelize para PostgreSQL).
 */

// Array que armazena todos os livros da aplicação.
// Cada livro é um objeto com propriedades bem definidas.
let books = [];

/**
 * Variável auxiliar para gerar IDs únicos automaticamente.
 * Em produção, use UUIDs ou IDs gerados pelo banco de dados.
 */
let nextId = 1;

/**
 * ============================================================
 * FUNÇÕES DO MODELO — Operações CRUD sobre o array em memória
 * ============================================================
 */

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista completa de livros.
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 * @param {number} id - O identificador único do livro.
 * @returns {Object|null} O livro encontrado ou null se não existir.
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 * Atribui automaticamente um ID sequencial.
 * @param {Object} bookData - Dados do novo livro (sem id).
 * @returns {Object} O livro criado com seu ID atribuído.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,          // ID sequencial auto-incrementado
    ...bookData            // Espalha as propriedades fornecidas
  };
  books.push(newBook);       // Adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo seu ID.
 * Mescla os campos enviados com os dados existentes (partial update).
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados.
 * @returns {Object|null} O livro atualizado ou null se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return null;

  // Mescla os dados existentes com as atualizações
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Remove um livro do array pelo seu ID.
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} True se foi removido, false caso contrário.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);    // Remove exatamente um elemento no índice encontrado
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o catálogo de livros.
 * @returns {Object} Estatísticas: total, média de preço, livros por autor, etc.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      totalLivros: 0,
      mediaPreco: 0,
      precoMinimo: null,
      precoMaximo: null,
      livrosPorAutor: {},
      autoresUnicos: 0
    };
  }

  // Calcula a média dos preços usando reduce para acumulação
  const somaPrecos = books.reduce((acc, book) => acc + book.preco, 0);
  const mediaPreco = parseFloat((somaPrecos / total).toFixed(2));

  // Encontra preço mínimo e máximo
  const precos = books.map(book => book.preco);
  const precoMinimo = Math.min(...precos);
  const precoMaximo = Math.max(...precos);

  // Agrupa livros por autor usando um objeto como mapa
  const livrosPorAutor = {};
  books.forEach(book => {
    const autor = book.autor || 'Desconhecido';
    if (!livrosPorAutor[autor]) {
      livrosPorAutor[autor] = 0;
    }
    livrosPorAutor[autor]++;
  });

  return {
    totalLivros: total,
    mediaPreco,
    precoMinimo,
    precoMaximo,
    livrosPorAutor,
    autoresUnicos: Object.keys(livrosPorAutor).length
  };
}

/**
 * Exporta todas as funções do modelo usando CommonJS.
 * O módulo é importado nas rotas para operações de dados.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
