## Arquivo 3: `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ---------------------------------------
 * Classes de erro personalizadas permitem:
 *   - Diferenciar tipos de erro (404, 400, 500) no middleware.
 *   - Incluir metadados adicionais (como campo inválido).
 *   - Manter o código de status HTTP correto em cada cenário.
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * ------------------------------
 * No Express, middlewares de erro têm 4 parâmetros (err, req, res, next).
 * Eles capturam erros lançados em qualquer rota ou middleware anterior,
 * centralizando o tratamento e evitando respostas inconsistentes.
 */

/**
 * Classe base para erros da API.
 * Estende Error nativo do JavaScript para manter compatibilidade com stack traces.
 */
class ApiError extends Error {
  /**
   * @param {number} statusCode - Código HTTP de status (ex: 404, 400).
   * @param {string} message - Mensagem descritiva do erro.
   * @param {Object} [metadata] - Dados adicionais sobre o erro (opcional).
   */
  constructor(statusCode, message, metadata = {}) {
    super(message);
    this.statusCode = statusCode;
    this.metadata = metadata;

    // Mantém a pilha de chamadas correta para debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro quando o recurso solicitado não é encontrado.
 * Ex: Livro com ID inexistente.
 */
class NotFoundError extends ApiError {
  constructor(resource = 'Recurso') {
    super(404, `${resource} não encontrado`);
    this.resource = resource;
  }
}

/**
 * Erro quando a requisição contém dados inválidos.
 * Ex: Campo obrigatório ausente ou formato incorreto.
 */
class ValidationError extends ApiError {
  constructor(message, field) {
    super(400, message);
    this.field = field;
  }
}

/**
 * Middleware genérico de tratamento de erros.
 * Deve ser registrado POR ÚLTIMO na cadeia de middlewares do Express.
 *
 * @param {Error} err - O erro capturado.
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função next do Express (não usada aqui).
 */
function errorHandler(err, req, res, next) {
  // Se o erro for da nossa API personalizada, usa seu statusCode
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, enviamos o stack trace para facilitar debugging.
  // Em produção, isso seria suprimido por segurança.
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      ...(isDevelopment && { stack: err.stack }), // Só em dev
      ...(err.field && { field: err.field }),     // Campo inválido (se houver)
      ...(err.resource && { resource: err.resource }) // Tipo de recurso (se houver)
    }
  });
}

/**
 * Middleware de validação de campos obrigatórios.
 * Verifica se todos os campos especificados estão presentes e não vazios.
 *
 * @param {...string} fields - Nomes dos campos obrigatórios.
 * @returns {Function} Middleware Express.
 */
function validateRequired(...fields) {
  return (req, res, next) => {
    // Verifica cada campo obrigatório
    const missingFields = fields.filter(field => {
      const value = req.body[field];
      return value === undefined || value === null || value === '';
    });

    if (missingFields.length > 0) {
      // Lança ValidationError com detalhes do primeiro campo faltante
      throw new ValidationError(
        `Campos obrigatórios ausentes: ${missingFields.join(', ')}`,
        missingFields[0]
      );
    }

    next(); // Continua para a próxima rota/middleware
  };
}

/**
 * Middleware de validação de tipo numérico para IDs.
 * Garante que o parâmetro :id seja um número válido.
 *
 * @returns {Function} Middleware Express.
 */
function validateIdParam(req, res, next) {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    throw new ValidationError('ID deve ser um número inteiro positivo', 'id');
  }

  // Substitui o parâmetro string pelo número convertido
  req.params.id = id;
  next();
}

// Exporta classes e middlewares para uso nas rotas
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler,
  validateRequired,
  validateIdParam
};
```

