## Arquivo 4: `src/routes/books.js` — Rotas da API

```javascript
/**
 * ============================================================
 * ROTAS DA API — CRUD de Livros
 * ============================================================
 *
 * POR QUE CONVENÇÕES REST?
 * -----------------------
 * REST (Representational State Transfer) é um estilo arquitetural
 * que mapeia métodos HTTP para operações CRUD:
 *   GET    → leitura (listar / obter)
 *   POST   → criação
 *   PUT    → atualização completa
 *   DELETE → remoção
 *
 * Isso torna a API previsível e fácil de entender para qualquer
 * desenvolvedor que conheça os padrões da web.
 *
 * POR QUE ASYNC/AWAIT?
 * -------------------
 * Async/await torna o código assíncrono mais legível, evitando
 * "callback hell" (aninhamento excessivo). Mesmo que esta API
 * use operações síncronas em memória, a estrutura async/await
 * prepara o código para migração futura a um banco de dados real.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente

// Importa funções do modelo e middlewares de validação
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
} = require('../models/books');

const { validateRequired, validateIdParam } = require('../middleware/errorHandler');

/**
 * ============================================================
 * GET /books — Listar todos os livros (com filtragem opcional)
 * ============================================================
 *
 * Query parameters suportados:
 *   - author  : filtra por nome do autor (case-insensitive)
 *   - minPrice: preço mínimo (número)
 *   - maxPrice: preço máximo (número)
 *
 * Exemplo de uso com curl:
 *   curl http://localhost:3000/books?author=jk&minPrice=10&maxPrice=50
 */
router.get('/books', (req, res) => {
  // Começa com a lista completa de livros
  let result = getAllBooks();

  // Filtra por autor se o parâmetro "author" estiver presente na query string
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter(book =>
      book.autor.toLowerCase().includes(authorFilter)
    );
  }

  // Filtra por preço mínimo se fornecido
  if (req.query.minPrice) {
    const minPrice = parseFloat(req.query.minPrice);
    result = result.filter(book => book.preco >= minPrice);
  }

  // Filtra por preço máximo se fornecido
  if (req.query.maxPrice) {
    const maxPrice = parseFloat(req.query.maxPrice);
    result = result.filter(book => book.preco <= maxPrice);
  }

  // Retorna os livros filtrados com status 200 (OK)
  res.json({
    success: true,
    count: result.length,           // Quantidade de livros na resposta
    data: result                    // Array de livros
  });
});

/**
 * ============================================================
 * GET /books/stats — Estatísticas do catálogo
 * ============================================================
 *
 * Retorna métricas agregadas sobre os livros cadastrados.
 * Útil para dashboards e monitoramento.
 *
 * Exemplo de uso com curl:
 *   curl http://localhost:3000/books/stats
 */
router.get('/books/stats', (req, res) => {
  const stats = getStats();

  res.json({
    success: true,
    data: stats
  });
});

/**
 * ============================================================
 * GET /books/:id — Obter um livro pelo ID
 * ============================================================
 *
 * O middleware validateIdParam garante que :id seja um número válido.
 * Se o livro não for encontrado, o middleware de erro retorna 404.
 *
 * Exemplo de uso com curl:
 *   curl http://localhost:3000/books/1
 */
router.get('/books/:id', validateIdParam, (req, res) => {
  const book = getBookById(req.params.id);

  if (!book) {
    // Lança NotFoundError que será capturado pelo middleware de erro
    throw new (require('../middleware/errorHandler').NotFoundError)('Livro');
  }

  res.json({
    success: true,
    data: book
  });
});

/**
 * ============================================================
 * POST /books — Criar um novo livro
 * ============================================================
 *
 * O middleware validateRequired garante que título e autor estejam presentes.
 * O ID é gerado automaticamente pelo modelo.
 *
 * Corpo esperado (JSON):
 *   { "titulo": "O Senhor dos Anéis", "autor": "J.R.R. Tolkien", "preco": 59.90 }
 *
 * Exemplo de uso com curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"titulo":"1984","autor":"George Orwell","preco":35.50}'
 */
router.post('/books',
  validateRequired('titulo', 'autor', 'preco'), // Valida campos obrigatórios
  (req, res) => {
    const { titulo, autor, preco } = req.body;

    // Cria o livro no modelo e recebe o objeto completo com ID atribuído
    const newBook = createBook({ titulo, autor, preco });

    // Status 201 (Created) indica que um novo recurso foi criado com sucesso
    res.status(201).json({
      success: true,
      data: newBook
    });
  }
);

/**
 * ============================================================
 * PUT /books/:id — Atualizar completamente um livro existente
 * ============================================================
 *
 * PUT exige que TODOS os campos sejam enviados (atualização completa).
 * Para atualizações parciais, use PATCH.
 *
 * Corpo esperado (JSON):
 *   { "titulo": "Novo Título", "autor": "Novo Autor", "preco": 45.00 }
 *
 * Exemplo de uso com curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"titulo":"O Senhor dos Anéis (Ed. Definitiva)","autor":"J.R.R. Tolkien","preco":79.90}'
 */
router.put('/books/:id',
  validateIdParam,
  validateRequired('titulo', 'autor', 'preco'),
  (req, res) => {
    const { titulo, autor, preco } = req.body;
    const updatedBook = updateBook(req.params.id, { titulo, autor, preco });

    if (!updatedBook) {
      throw new (require('../middleware/errorHandler').NotFoundError)('Livro');
    }

    // Status 200 (OK) com o recurso atualizado retornado
    res.json({
      success: true,
      data: updatedBook
    });
  }
);

/**
 * ============================================================
 * DELETE /books/:id — Excluir um livro pelo ID
 * ============================================================
 *
 * Retorna status 204 (No Content) quando a exclusão é bem-sucedida,
 * pois não há conteúdo para retornar no corpo da resposta.
 *
 * Exemplo de uso com curl:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', validateIdParam, (req, res) => {
  const deleted = deleteBook(req.params.id);

  if (!deleted) {
    throw new (require('../middleware/errorHandler').NotFoundError)('Livro');
  }

  // Status 204 indica sucesso sem corpo de resposta
  res.status(204).send();
});

// Exporta o roteador para ser usado no app principal
module.exports = router;
```

