## Arquivo 5: `src/app.js` — Configuração do Aplicativo Express

```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DO APLICATIVO EXPRESS
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * ------------------------------------
 * - app.js configura o aplicativo (middlewares, rotas).
 * - server.js apenas inicia o servidor HTTP e define a porta.
 * Essa separação permite testar o app sem precisar iniciar o servidor.
 */

const express = require('express');
const booksRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a instância do aplicativo Express
const app = express();

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 */

// Middleware para parsear JSON no corpo das requisições.
// Sem isso, req.body seria undefined em requisições POST/PUT.
app.use(express.json());

// Middleware para log de todas as requisições (útil para debugging).
// Registra método, URL e timestamp de cada request.
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

/**
 * ============================================================
 * REGISTRO DE ROTAS
 * ============================================================
 *
 * Todas as rotas de livros estão agrupadas sob o prefixo /books.
 * O roteador é montado com app.use(), que encaminha requisições
 * cujo caminho começa com '/books' para o módulo de rotas.
 */
app.use('/books', booksRoutes);

/**
 * ============================================================
 * ROTA DE HEALTH CHECK
 * ============================================================
 *
 * Endpoint simples para verificar se a API está respondendo.
 * Comum em sistemas de orquestração (Kubernetes, Docker Swarm).
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando com sucesso!',
    endpoints: {
      list:       'GET    /books',
      stats:      'GET    /books/stats',
      getById:    'GET    /books/:id',
      create:     'POST   /books',
      update:     'PUT    /books/:id',
      remove:     'DELETE /books/:id'
    }
  });
});

/**
 * ============================================================
 * ROTA 404 — Recurso não encontrado
 * ============================================================
 *
 * Captura requisições para rotas que não foram definidas.
 * Lança um erro que será tratado pelo middleware de erro global.
 */
app.use((req, res, next) => {
  const err = new Error(`Rota ${req.method} ${req.url} não encontrada`);
  err.statusCode = 404;
  next(err); // Passa o erro para o middleware de tratamento
});

/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS (GLOBAL)
 * ============================================================
 *
 * Deve ser o ÚLTIMO middleware registrado.
 * Captura erros de todas as rotas e middlewares anteriores.
 */
app.use(errorHandler);

// Exporta a instância do app para uso em server.js e testes
module.exports = app;
```

