## Arquivo 6: `src/server.js` — Inicialização do Servidor

```javascript
/**
 * ============================================================
 * INICIALIZAÇÃO DO SERVIDOR HTTP
 * ============================================================
 *
 * Este arquivo apenas cria o servidor HTTP e o coloca para
 * ouvir na porta configurada. A lógica da aplicação está em app.js.
 */

const app = require('./app');

// Define a porta: usa variável de ambiente PORT ou padrão 3000
const PORT = process.env.PORT || 3000;

// Cria o servidor HTTP a partir do aplicativo Express
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
});

// Graceful shutdown: limpa recursos ao receber sinal de interrupção
process.on('SIGTERM', () => {
  console.log('\nSinal SIGTERM recebido. Encerrando servidor...');
  server.close(() => {
    console.log('Servidor encerrado com sucesso.');
    process.exit(0);
  });
});

module.exports = server;
```

