/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - O ID do livro a ser encontrado
 * @returns {Object|null} O livro encontrado ou null se não existir
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} bookData - Dados do livro a ser criado
 * @param {string} bookData.title - Título do livro (obrigatório)
 * @param {string} bookData.author - Autor do livro (obrigatório)
 * @param {number} [bookData.year] - Ano de publicação
 * @param {string} [bookData.genre] - Gênero literário
 * @param {string} [bookData.isbn] - ISBN do livro
 * @returns {Object} O livro criado com ID e timestamps atribuídos
 */
function createBook(bookData) {
  const now = new Date().toISOString();

  const newBook = {
    id: nextId++,
    title: bookData.title,
    author: bookData.author,
    year: bookData.year || null,
    genre: bookData.genre || null,
    isbn: bookData.isbn || null,
    createdAt: now,
    updatedAt: now
  };

  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados (partial update)
 * @returns {Object|null} O livro atualizado ou null se não encontrado
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return null;
  }

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // e sempre atualiza o timestamp de modificação.
  books[index] = {
    ...books[index],
    ...updates,
    updatedAt: new Date().toISOString()
  };

  return books[index];
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} True se o livro foi encontrado e removido, false caso contrário
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false;
  }

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas incluindo total de livros, média de anos,
 *                   distribuição por gênero e autores mais frequentes.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total: 0,
      averageYear: null,
      genres: {},
      authors: {}
    };
  }

  // Calcula a média dos anos de publicação
  const sumYears = books.reduce((acc, book) => acc + (book.year || 0), 0);
  const averageYear = Math.round(sumYears / total);

  // Conta livros por gênero
  const genres = {};
  books.forEach(book => {
    if (book.genre) {
      genres[book.genre] = (genres[book.genre] || 0) + 1;
    }
  });

  // Conta livros por autor
  const authors = {};
  books.forEach(book => {
    if (book.author) {
      authors[book.author] = (authors[book.author] || 0) + 1;
    }
  });

  return {
    total,
    averageYear,
    genres,
    authors
  };
}

