## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Tratamento Centralizado de Erros
 * ============================================================
 *
 * Este middleware implementa um sistema robusto de tratamento de erros
 * com classes personalizadas e um handler global.
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ----------------------------------------
 * Classes como NotFoundError, ValidationError e InternalError permitem:
 * 1. Identificar o tipo de erro programaticamente no handler.
 * 2. Incluir campos extras (ex: campo que falhou na validação).
 * 3. Manter mensagens de erro consistentes e estruturadas.
 * 4. Diferenciar erros do cliente (4xx) de erros do servidor (5xx).
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * -------------------------------
 * No Express, middlewares de erro têm a assinatura especial (err, req, res, next).
 * Eles capturam erros lançados em qualquer rota e padronizam a resposta JSON.
 * Isso evita repetir blocos try/catch em cada handler e garante que nenhum
 * erro escape sem uma resposta adequada ao cliente.
 * ============================================================
 */

/**
 * Classe base para todos os erros da API.
 *
 * Estende Error nativo do JavaScript para manter compatibilidade com o stack trace.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível
   * @param {number} statusCode - Código HTTP de status (padrão: 500)
   * @param {boolean} isOperational - Se é um erro operacional (não deve ser logado como bug)
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Captura o nome da classe para identificação no handler
    this.name = this.constructor.name;

    // Mantém o stack trace limpo (remove a linha do construtor da classe base)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID inválido é fornecido ou recurso não existe.
 */
class NotFoundError extends ApiError {
  constructor(resource = 'recurso') {
    super(`${resource} não encontrado`, 404, true);
  }
}

/**
 * Erro 400 — Validação falhou.
 * Usado quando dados enviados pelo cliente não atendem aos requisitos.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message - Mensagem de erro
   * @param {Array<Object>} [details] - Lista de campos com erros e suas mensagens
   */
  constructor(message = 'Dados inválidos', details = []) {
    super(message, 400, true);
    this.details = details;
  }
}

/**
 * Erro 500 — Erro interno do servidor.
 * Usado para erros inesperados que não são causados por entrada do cliente.
 */
class InternalError extends ApiError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, false); // false = erro operacional = NÃO é bug, mas sim esperado
  }
}

/**
 * Middleware de tratamento de erros global do Express.
 *
 * Este middleware DEVE ser o último registrado (após todas as rotas).
 * O Express identifica middlewares de erro pela assinatura de 4 parâmetros.
 *
 * @param {Error} err - O objeto de erro capturado
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função next (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Log do erro no servidor para depuração
  console.error(`[${err.name}] ${err.message}`);
  if (process.env.NODE_ENV === 'development' && err.stack) {
    console.error(err.stack);
  }

  // Estrutura padronizada de resposta de erro
  const errorResponse = {
    success: false,
    error: {
      name: err.name,
      message: err.message
    },
    timestamp: new Date().toISOString()
  };

  // Adiciona detalhes de validação quando disponíveis
  if (err.details && err.details.length > 0) {
    errorResponse.error.details = err.details;
  }

  // Responde com o status code apropriado
  res.status(err.statusCode).json(errorResponse);
}

/**
 * Middleware que captura erros de rotas assíncronas.
 *
 * POR QUE ESTE WRAPPER?
 * ---------------------
 * Express não captura automaticamente rejeições de Promises em handlers async.
 * Se um handler async lança um erro, o Express não o encaminha para o middleware
 * de erro — a requisição simplesmente "pendura". Este wrapper envolve cada handler
 * para capturar erros síncronos e assíncronos igualmente.
 *
 * @param {Function} fn - Handler assíncrono a ser envolvido
 * @returns {Function} Handler Express com tratamento de erro embutido
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  InternalError,
  errorHandler,
  asyncHandler
};
```

