## Arquivo 4: `src/middleware/validator.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Validação de Entrada
 * ============================================================
 *
 * Middleware que valida os dados enviados pelo cliente antes
 * que cheguem aos handlers das rotas.
 *
 * POR QUE VALIDAR NO MIDDLEWARE E NÃO NO MODEL?
 * ----------------------------------------------
 * Separar validação do model segue o princípio de responsabilidade única:
 * - O middleware se preocupa com a forma dos dados (input validation)
 * - O model se preocupa com as operações de negócio (CRUD)
 * Isso torna ambos mais testáveis e reutilizáveis.
 * ============================================================
 */

const { ValidationError } = require('./errorHandler');

/**
 * Valida os campos obrigatórios para criação de um livro.
 *
 * Regras:
 * - title: string não vazia (mínimo 1 caractere, máximo 500)
 * - author: string não vazia (mínimo 1 caractere, máximo 200)
 * - year: se fornecido, deve ser um número inteiro entre 0 e 2100
 * - genre: se fornecido, deve ser uma string não vazia
 * - isbn: se fornecido, deve ter formato ISBN válido (10 ou 13 dígitos)
 *
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {Function} next - Função next do Express
 * @throws {ValidationError} Se a validação falhar
 */
function validateCreateBook(req, res, next) {
  const { title, author, year, genre, isbn } = req.body;

  const errors = [];

  // Valida título
  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    errors.push({ field: 'title', message: 'Título é obrigatório e deve ser uma string não vazia' });
  } else if (title.length > 500) {
    errors.push({ field: 'title', message: 'Título deve ter no máximo 500 caracteres' });
  }

  // Valida autor
  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    errors.push({ field: 'author', message: 'Autor é obrigatório e deve ser uma string não vazia' });
  } else if (author.length > 200) {
    errors.push({ field: 'author', message: 'Autor deve ter no máximo 200 caracteres' });
  }

  // Valida ano (opcional, mas se fornecido deve ser válido)
  if (year !== undefined && year !== null) {
    const numYear = Number(year);
    if (!Number.isInteger(numYear) || numYear < 0 || numYear > 2100) {
      errors.push({ field: 'year', message: 'Ano deve ser um número inteiro entre 0 e 2100' });
    }
  }

  // Valida gênero (opcional)
  if (genre !== undefined && genre !== null) {
    if (typeof genre !== 'string' || genre.trim().length === 0) {
      errors.push({ field: 'genre', message: 'Gênero deve ser uma string não vazia' });
    }
  }

  // Valida ISBN (opcional, formato flexível)
  if (isbn !== undefined && isbn !== null) {
    const cleanedIsbn = String(isbn).replace(/[-\s]/g, '');
    if (!/^\d{10}$/.test(cleanedIsbn) && !/^\d{13}$/.test(cleanedIsbn)) {
      errors.push({ field: 'isbn', message: 'ISBN deve ter 10 ou 13 dígitos numéricos' });
    }
  }

  if (errors.length > 0) {
    return next(new ValidationError('Validação falhou', errors));
  }

  // Limpa campos antes de passar ao model (trim de strings)
  req.body.title = title.trim();
  req.body.author = author.trim();
  if (year !== undefined && year !== null) {
    req.body.year = Number(year);
  } else {
    req.body.year = null;
  }

  next();
}

/**
 * Valida o parâmetro de ID na URL.
 *
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {Function} next - Função next do Express
 * @throws {ValidationError} Se o ID não for um número inteiro válido
 */
function validateIdParam(req, res, next) {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new ValidationError('ID inválido. Deve ser um número inteiro positivo.', [
      { field: 'id', message: 'O parâmetro :id deve ser um número inteiro válido' }
    ]));
  }

  // Passa o ID como número para os handlers
  req.params.id = id;
  next();
}

module.exports = {
  validateCreateBook,
  validateIdParam
};
