## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS: Livros (Books)
 * ============================================================
 *
 * Este arquivo contém todas as rotas REST para o recurso "livros".
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar rotas em arquivos distintos segue a convenção de modularização do Express:
 * 1. Facilita a manutenção — cada recurso tem seu próprio arquivo.
 * 2. Permite escalar — quando a API crescer, basta adicionar novos arquivos de rota.
 * 3. Melhora a legibilidade — handlers específicos ficam organizados por recurso.
 * 4. Facilita testes — podemos testar rotas isoladamente.
 *
 * CONVENÇÕES REST ADOTADAS:
 * -------------------------
 * - GET    /books       → Listar todos (com filtragem e paginação)
 * - GET    /books/:id    → Obter um livro específico
 * - POST   /books       → Criar novo livro
 * - PUT    /books/:id    → Atualizar completamente um livro
 * - DELETE /books/:id    → Excluir um livro
 * - GET    /stats        → Estatísticas agregadas (recurso derivado)
 *
 * Cada rota retorna JSON com estrutura padronizada:
 * { success: true/false, data?: ..., error?: ... }
 * ============================================================
 */

const express = require('express');
const router = express.Router();

// Importa o model e utilitários
const bookModel = require('../models/book');
const { asyncHandler, NotFoundError, ValidationError } = require('../middleware/errorHandler');
const { validateCreateBook, validateIdParam } = require('../middleware/validator');

/**
 * ============================================================
 * SEÇÃO 1: GET /books — Listar todos os livros com filtragem
 * ============================================================
 *
 * Suporta query parameters para filtragem avançada:
 * - ?author=nome       → Filtra por autor (case-insensitive, partial match)
 * - ?genre=gênero      → Filtra por gênero (exato)
 * - ?title=título      → Filtra por título (partial match, case-insensitive)
 * - ?year=1984         → Filtra por ano exato
 * - ?minYear=1900      → Filtra livros publicados após 1900
 * - ?maxYear=2000      → Filtra livros publicados antes de 2000
 * - ?sort=year:asc     → Ordena por campo (title, author, year) com direção
 * - ?page=1            → Número da página (padrão: 1)
 * - ?limit=10          → Itens por página (padrão: 10, máximo: 100)
 *
 * Exemplo de uso:
 *   curl "http://localhost:3000/books?genre=Fantasia&sort=year:asc&page=1&limit=5"
 *   curl "http://localhost:3000/books?author=tolkien&minYear=1900"
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Obtém todos os livros do model
    let result = bookModel.getAllBooks();

    // --- FILTRAGEM ---
    const { author, genre, title, year, minYear, maxYear } = req.query;

    if (author) {
      // Partial match case-insensitive: "tolkien" encontra "J.R.R. Tolkien"
      const searchLower = author.toLowerCase();
      result = result.filter(book => book.author.toLowerCase().includes(searchLower));
    }

    if (genre) {
      // Match exato de gênero (case-insensitive)
      result = result.filter(book => book.genre && book.genre.toLowerCase() === genre.toLowerCase());
    }

    if (title) {
      const searchLower = title.toLowerCase();
      result = result.filter(book => book.title.toLowerCase().includes(searchLower));
    }

    if (year) {
      const numYear = Number(year);
      result = result.filter(book => book.year === numYear);
    }

    if (minYear) {
      const min = Number(minYear);
      result = result.filter(book => book.year && book.year >= min);
    }

    if (maxYear) {
      const max = Number(maxYear);
      result = result.filter(book => book.year && book.year <= max);
    }

    // --- ORDENAÇÃO ---
    const { sort } = req.query;
    if (sort) {
      const [field, direction] = sort.split(':');
      const validFields = ['title', 'author', 'year', 'createdAt'];
      const validDirections = ['asc', 'desc'];

      if (validFields.includes(field) && validDirections.includes(direction)) {
        result.sort((a, b) => {
          let valA = a[field] || '';
          let valB = b[field] || '';

          // Converte para número se for ano
          if (field === 'year') {
            valA = Number(valA) || 0;
            valB = Number(valB) || 0;
          } else {
            valA = String(valA).toLowerCase();
            valB = String(valB).toLowerCase();
          }

          if (valA < valB) return direction === 'asc' ? -1 : 1;
          if (valA > valB) return direction === 'asc' ? 1 : -1;
          return 0;
        });
      }
    }

    // --- PAGINAÇÃO ---
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 10));
    const total = result.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const paginatedResult = result.slice(startIndex, startIndex + limit);

    // Resposta padronizada com metadados de paginação
    res.json({
      success: true,
      data: paginatedResult,
      pagination: {
        page,
        limit,
        total,
        totalPages,
        hasNextPage: page < totalPages,
        hasPrevPage: page > 1
      }
    });
  })
);

/**
 * ============================================================
 * SEÇÃO 2: GET /books/:id — Obter um livro por ID
 * ============================================================
 *
 * Exemplo de uso:
 *   curl "http://localhost:3000/books/1"
 *   curl "http://localhost:3000/books/999"  → retorna 404
 */
router.get(
  '/books/:id',
  validateIdParam, // Middleware que valida e converte o ID para número
  asyncHandler(async (req, res) => {
    const book = bookModel.getBookById(req.params.id);

    if (!book) {
      throw new NotFoundError('Livro');
    }

    res.json({
      success: true,
      data: book
    });
  })
);

/**
 * ============================================================
 * SEÇÃO 3: POST /books — Criar novo livro
 * ============================================================
 *
 * Corpo esperado (JSON):
 * {
 *   "title": "Novo Livro",
 *   "author": "Autor Exemplo",
 *   "year": 2024,
 *   "genre": "Ficção",
 *   "isbn": "978-0000000000"
 * }
 *
 * Campos opcionais: year, genre, isbn (title e author são obrigatórios)
 *
 * Exemplo de uso:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Nome da Rosa","author":"Umberto Eco","year":1980,"genre":"Mistério"}'
 */
router.post(
  '/books',
  validateCreateBook, // Middleware de validação
  asyncHandler(async (req, res) => {
    const newBook = bookModel.createBook(req.body);

    // Status 201 Created indica que um recurso foi criado com sucesso
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso'
    });
  })
);

/**
 * ============================================================
 * SEÇÃO 4: PUT /books/:id — Atualizar livro existente
 * ============================================================
 *
 * Diferença entre PUT e PATCH:
 * - PUT substitui o recurso inteiro (todos os campos são atualizados)
 * - PATCH atualiza apenas campos específicos
 *
 * Neste exemplo, usamos semântica de PUT mas permitimos partial update
 * (atualiza apenas os campos enviados), combinando com timestamp automático.
 *
 * Exemplo de uso:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis (Edição Ilustrada)"}'
 */
router.put(
  '/books/:id',
  validateIdParam,
  asyncHandler(async (req, res) => {
    const book = bookModel.getBookById(req.params.id);

    if (!book) {
      throw new NotFoundError('Livro');
    }

    // Valida campos opcionais se forem fornecidos
    const updates = {};
    const { title, author, year, genre, isbn } = req.body;

    if (title !== undefined) {
      if (typeof title !== 'string' || title.trim().length === 0) {
        throw new ValidationError('Título deve ser uma string não vazia', [
          { field: 'title', message: 'Título é obrigatório quando fornecido' }
        ]);
      }
      updates.title = title.trim();
    }

    if (author !== undefined) {
      if (typeof author !== 'string' || author.trim().length === 0) {
        throw new ValidationError('Autor deve ser uma string não vazia', [
          { field: 'author', message: 'Autor é obrigatório quando fornecido' }
        ]);
      }
      updates.author = author.trim();
    }

    if (year !== undefined) {
      const numYear = Number(year);
      if (!Number.isInteger(numYear) || numYear < 0 || numYear > 2100) {
        throw new ValidationError('Ano inválido', [
          { field: 'year', message: 'Ano deve ser um número inteiro entre 0 e 2100' }
        ]);
      }
      updates.year = numYear;
    }

    if (genre !== undefined) {
      if (typeof genre !== 'string' || genre.trim().length === 0) {
        throw new ValidationError('Gênero inválido', [
          { field: 'genre', message: 'Gênero deve ser uma string não vazia' }
        ]);
      }
      updates.genre = genre.trim();
    }

    if (isbn !== undefined) {
      const cleanedIsbn = String(isbn).replace(/[-\s]/g, '');
      if (!/^\d{10}$/.test(cleanedIsbn) && !/^\d{13}$/.test(cleanedIsbn)) {
        throw new ValidationError('ISBN inválido', [
          { field: 'isbn', message: 'ISBN deve ter 10 ou 13 dígitos numéricos' }
        ]);
      }
      updates.isbn = isbn;
    }

    // Se nenhum campo válido foi fornecido, retorna erro
    if (Object.keys(updates).length === 0) {
      throw new ValidationError('Nenhum campo válido para atualização fornecido', [
        { field: 'body', message: 'Forneça pelo menos um campo para atualizar' }
      ]);
    }

    const updatedBook = bookModel.updateBook(req.params.id, updates);

    res.json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso'
    });
  })
);

/**
 * ============================================================
 * SEÇÃO 5: DELETE /books/:id — Excluir livro
 * ============================================================
 *
 * Exemplo de uso:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete(
  '/books/:id',
  validateIdParam,
  asyncHandler(async (req, res) => {
    const deleted = bookModel.deleteBook(req.params.id);

    if (!deleted) {
      throw new NotFoundError('Livro');
    }

    // Status 204 No Content indica sucesso sem corpo de resposta
    // Aqui optamos por retornar 200 com confirmação para melhor debugging
    res.json({
      success: true,
      message: 'Livro excluído com sucesso'
    });
  })
);

/**
 * ============================================================
 * SEÇÃO 6: GET /stats — Estatísticas agregadas dos livros
 * ============================================================
 *
 * Retorna métricas como total de livros, média de anos de publicação,
 * distribuição por gênero e contagem por autor.
 *
 * Exemplo de uso:
 *   curl "http://localhost:3000/stats"
 */
router.get(
  '/stats',
  asyncHandler(async (req, res) => {
    const stats = bookModel.getStats();

    res.json({
      success: true,
      data: stats
    });
  })
);

module.exports = router;
```

