```javascript
/**
 * ============================================================
 * APP PRINCIPAL — Configuração do Express
 * ============================================================
 *
 * Este arquivo configura a aplicação Express com:
 * - Middlewares globais (JSON parsing, logging)
 * - Rotas da API
 * - Middleware de tratamento de erros
 * - Rota de health check
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * - app.js configura a aplicação (middleware, rotas)
 * - server.js apenas inicia o servidor HTTP e ouve uma porta
 * Isso permite testar a aplicação sem precisar iniciar um servidor.
 * ============================================================
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

const app = express();

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 */

// Parseia corpos de requisição JSON automaticamente.
// Sem este middleware, req.body seria undefined em POST/PUT.
app.use(express.json());

// Middleware de logging simples para depuração
// Mostra método, URL e timestamp de cada requisição
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

/**
 * ============================================================
 * ROTAS DA API
 * ============================================================
 */

// Rota de health check — útil para monitoramento e load balancers
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Registra as rotas de livros no prefixo /api/v1
// O versionamento na URL (/v1) é uma convenção REST que facilita
// a evolução da API sem quebrar clientes existentes.
app.use('/api/v1', bookRoutes);

/**
 * ============================================================
 * TRATAMENTO DE ERROS
 * ============================================================
 *
 * O middleware de erro deve ser o ÚLTIMO middleware registrado.
 * Express encadeia middlewares na ordem em que são definidos,
 * e middlewares de erro só são chamados quando next(err) é invocado.
 * ============================================================
 */
app.use(errorHandler);

/**
 * ============================================================
 * ROTA 404 — Recurso não encontrado (catch-all)
 * ============================================================
 *
 * Esta rota captura todas as requisições para URLs que não
 * correspondem a nenhuma rota definida, retornando 404.
 * Ela DEVE vir após todas as outras rotas e antes do middleware de erro.
 * ============================================================
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./middleware/errorHandler');
  next(new NotFoundError('Endpoint'));
});

module.exports = app;
```

