## File 2 — `middleware/errorHandler.js`

```javascript
/**
 * Custom error classes and a global Express error-handling middleware.
 *
 * WHY custom error classes?
 *   - They let us distinguish between different failure modes (not-found vs validation).
 *   - The global handler can inspect the error type and return an appropriate HTTP status code
 *     without scattering try/catch blocks everywhere.
 *
 * WHY a single error-handling middleware?
 *   - Express supports a special 4-argument middleware: (err, req, res, next).
 *   - Placing it LAST ensures every route can simply call next(err) and rely on this handler.
 */

/**
 * Base class for all application errors.
 * Extends the built-in Error so we get a proper stack trace.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable description of the error.
   * @param {number} statusCode - HTTP status code (default 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    // Keep the name as 'AppError' for debugging.
    Object.setPrototypeOf(this, AppError.prototype);
  }
}

/**
 * Thrown when a requested resource does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
    Object.setPrototypeOf(this, NotFoundError.prototype);
  }
}

/**
 * Thrown when client input fails validation.
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
    Object.setPrototypeOf(this, ValidationError.prototype);
  }
}

/**
 * Global error-handling middleware.
 *
 * Express will ONLY invoke this function when next(err) is called somewhere upstream.
 * It formats a consistent JSON response regardless of which error occurred.
 *
 * @param {Error} err - The error object (instance of AppError or native Error).
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Unused but required by Express signature.
 */
const errorHandler = (err, req, res, next) => {
  // Default to 500 if the error didn't set a statusCode (e.g., unhandled exceptions).
  const status = err.statusCode || 500;

  // In production you might log `err.stack` to a file or monitoring service.
  console.error(`[ERROR] ${status} — ${err.message}`);

  res.status(status).json({
    success: false,
    error: {
      message: err.message,
      // Include the error type name for easier client-side handling.
      type: err.constructor.name,
    },
  });
};

module.exports = { AppError, NotFoundError, ValidationError, errorHandler };
```

