## File 3 — `routes/books.js`

```javascript
/**
 * Book CRUD routes.
 *
 * WHY separate route file?
 *   - Keeps server.js lean and focused on wiring middleware.
 *   - Makes it easy to add more resources (authors, reviews) later without clutter.
 *
 * Data structure choice: in-memory array of plain objects.
 *   - Simplest possible persistence for an educational example.
 *   - No database setup required; students can focus on API patterns.
 *   - Each book has: id (number), title (string), author (string), genre (string),
 *     publishedYear (number), rating (number, 1-5).
 */

const { AppError, NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ---------------------------------------------------------------------------
// In-memory store
// ---------------------------------------------------------------------------

/**
 * Array of book objects.
 * We use an array because order matters for list endpoints and we want O(1) access
 * by index when filtering. For a real app, a Map or database would be preferable.
 */
const books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: '1984', author: 'George Orwell', genre: 'Dystopian', publishedYear: 1949, rating: 4.7 },
  { id: 3, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
];

/**
 * Helper: generate the next sequential ID.
 * In production you'd use a database sequence or UUID.
 */
let nextId = 4;
const getNextId = () => nextId++;

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Validates the fields required for creating/updating a book.
 * Throws ValidationError with a descriptive message on failure.
 *
 * @param {object} body - The request body to validate.
 */
const validateBookBody = (body) => {
  const { title, author, genre, publishedYear, rating } = body;

  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string');
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    throw new ValidationError('Genre is required and must be a non-empty string');
  }
  if (publishedYear === undefined || publishedYear === null) {
    throw new ValidationError('Published year is required');
  }
  if (!Number.isInteger(publishedYear) || publishedYear < 0 || publishedYear > new Date().getFullYear() + 1) {
    throw new ValidationError('Published year must be a positive integer');
  }
  if (rating === undefined || rating === null) {
    throw new ValidationError('Rating is required');
  }
  const numRating = Number(rating);
  if (isNaN(numRating) || numRating < 1 || numRating > 5) {
    throw new ValidationError('Rating must be a number between 1 and 5');
  }
};

/**
 * Validates that an ID parameter is a positive integer.
 * Throws NotFoundError if the book with that ID doesn't exist.
 *
 * @param {number} id - The route parameter ID.
 * @returns {object} The found book object.
 */
const findBookById = (id) => {
  const book = books.find((b) => b.id === id);
  if (!book) {
    throw new NotFoundError('Book');
  }
  return book;
};

// ---------------------------------------------------------------------------
// Route definitions
// ---------------------------------------------------------------------------

/**
 * @typedef {import('express').Router} Router
 */

/**
 * Create and export an Express router instance.
 * All routes are defined inside this closure to keep the module self-contained.
 */
const createBookRoutes = () => {
  const router = require('express').Router();

  // ---------------------------------------------------------------------------
  // GET /books — List all books with optional filtering
  // ---------------------------------------------------------------------------
  /**
   * @name GET /books
   * @description Returns a paginated list of books. Supports query filters:
   *              ?genre=Fiction&minRating=4.0&page=1&limit=10
   * @param {string} [req.query.genre] - Filter by genre (case-insensitive).
   * @param {number} [req.query.minRating] - Minimum rating (1-5).
   * @param {number} [req.query.page] - Page number (default 1).
   * @param {number} [req.query.limit] - Items per page (default 10, max 50).
   * @returns {object} 200 — { success: true, data: [...], pagination: {...} }
   * @example curl http://localhost:3000/books?genre=Fiction&minRating=4.0
   */
  router.get('/', (req, res, next) => {
    try {
      // Destructure query parameters with defaults.
      const { genre, minRating, page = 1, limit = 10 } = req.query;

      // Start with a copy so we never mutate the original array.
      let filtered = [...books];

      // Apply filters if provided.
      if (genre) {
        const normalizedGenre = genre.trim().toLowerCase();
        filtered = filtered.filter((b) => b.genre.toLowerCase() === normalizedGenre);
      }
      if (minRating) {
        const min = Number(minRating);
        if (!isNaN(min)) {
          filtered = filtered.filter((b) => b.rating >= min);
        }
      }

      // Pagination math.
      const total = filtered.length;
      const totalPages = Math.ceil(total / limit);
      const currentPage = Math.max(1, Math.min(page, totalPages || 1));
      const startIndex = (currentPage - 1) * limit;
      const paginatedBooks = filtered.slice(startIndex, startIndex + limit);

      res.json({
        success: true,
        data: paginatedBooks,
        pagination: {
          total,
          totalPages,
          currentPage,
          limit,
        },
      });
    } catch (err) {
      next(err);
    }
  });

  // ---------------------------------------------------------------------------
  // GET /books/:id — Get a single book by ID
  // ---------------------------------------------------------------------------
  /**
   * @name GET /books/:id
   * @description Returns a single book object or 404 if not found.
   * @param {number} params.id - The numeric book ID.
   * @returns {object} 200 — { success: true, data: {...} }
   * @example curl http://localhost:3000/books/1
   */
  router.get('/:id', (req, res, next) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id < 1) {
        throw new ValidationError('Invalid book ID');
      }
      const book = findBookById(id);
      res.json({ success: true, data: book });
    } catch (err) {
      next(err);
    }
  });

  // ---------------------------------------------------------------------------
  // POST /books — Create a new book
  // ---------------------------------------------------------------------------
  /**
   * @name POST /books
   * @description Creates a new book from the request body.
   * @bodyparam {string} body.title - Book title (required).
   * @bodyparam {string} body.author - Author name (required).
   * @bodyparam {string} body.genre - Genre (required).
   * @bodyparam {number} body.publishedYear - Publication year (required, integer).
   * @bodyparam {number} body.rating - Rating 1-5 (required).
   * @returns {object} 201 — { success: true, data: {...} }
   * @example curl -X POST http://localhost:3000/books \
            -H "Content-Type: application/json" \
            -d '{"title":"Dune","author":"Frank Herbert","genre":"Sci-Fi","publishedYear":1965,"rating":4.6}'
   */
  router.post('/', (req, res, next) => {
    try {
      validateBookBody(req.body);

      const newBook = {
        id: getNextId(),
        title: req.body.title.trim(),
        author: req.body.author.trim(),
        genre: req.body.genre.trim(),
        publishedYear: Number(req.body.publishedYear),
        rating: Number(req.body.rating),
      };

      books.push(newBook);

      // 201 Created is the semantically correct status for resource creation.
      res.status(201).json({ success: true, data: newBook });
    } catch (err) {
      next(err);
    }
  });

  // ---------------------------------------------------------------------------
  // PUT /books/:id — Full update of an existing book
  // ---------------------------------------------------------------------------
  /**
   * @name PUT /books/:id
   * @description Replaces all fields of an existing book. Returns 404 if not found.
   * @bodyparam {string} body.title - Book title (required).
   * @bodyparam {string} body.author - Author name (required).
   * @bodyparam {string} body.genre - Genre (required).
   * @bodyparam {number} body.publishedYear - Publication year (required, integer).
   * @bodyparam {number} body.rating - Rating 1-5 (required).
   * @returns {object} 200 — { success: true, data: {...} }
   * @example curl -X PUT http://localhost:3000/books/1 \
            -H "Content-Type: application/json" \
            -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald","genre":"Fiction","publishedYear":1925,"rating":4.9}'
   */
  router.put('/:id', (req, res, next) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id < 1) {
        throw new ValidationError('Invalid book ID');
      }

      validateBookBody(req.body);

      // Find the index so we can replace in-place.
      const index = books.findIndex((b) => b.id === id);
      if (index === -1) {
        throw new NotFoundError('Book');
      }

      const updatedBook = {
        id,
        title: req.body.title.trim(),
        author: req.body.author.trim(),
        genre: req.body.genre.trim(),
        publishedYear: Number(req.body.publishedYear),
        rating: Number(req.body.rating),
      };

      books[index] = updatedBook;
      res.json({ success: true, data: updatedBook });
    } catch (err) {
      next(err);
    }
  });

  // ---------------------------------------------------------------------------
  // DELETE /books/:id — Remove a book
  // ---------------------------------------------------------------------------
  /**
   * @name DELETE /books/:id
   * @description Deletes a book by ID. Returns 204 No Content on success, 404 if not found.
   * @returns {void} 204 — Empty body.
   * @example curl -X DELETE http://localhost:3000/books/1
   */
  router.delete('/:id', (req, res, next) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id < 1) {
        throw new ValidationError('Invalid book ID');
      }

      const index = books.findIndex((b) => b.id === id);
      if (index === -1) {
        throw new NotFoundError('Book');
      }

      // Remove the book from the array.
      books.splice(index, 1);

      // 204 No Content is standard for successful DELETE with no response body.
      res.status(204).end();
    } catch (err) {
      next(err);
    }
  });

  return router;
};

module.exports = createBookRoutes;
```

