## File 4 — `routes/stats.js`

```javascript
/**
 * Statistics endpoint.
 *
 * WHY a separate route file?
 *   - Keeps concerns separated: books are resources, stats are aggregates.
 *   - Makes it easy to add more aggregate endpoints later (e.g., /stats/genres).
 */

const { AppError } = require('../middleware/errorHandler');

/**
 * In-memory reference — must match the same array used in routes/books.js.
 * In a larger app you'd import from a shared data module instead of duplicating.
 */
const books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: '1984', author: 'George Orwell', genre: 'Dystopian', publishedYear: 1949, rating: 4.7 },
  { id: 3, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
];

/**
 * @typedef {import('express').Router} Router
 */

const createStatsRoutes = () => {
  const router = require('express').Router();

  // ---------------------------------------------------------------------------
  // GET /stats — Aggregate statistics about the book collection
  // ---------------------------------------------------------------------------
  /**
   * @name GET /stats
   * @description Returns aggregate metrics: total books, average rating, genre distribution,
   *              oldest and newest publication years.
   * @returns {object} 200 — { success: true, data: {...} }
   * @example curl http://localhost:3000/stats
   */
  router.get('/', (req, res, next) => {
    try {
      const totalBooks = books.length;

      if (totalBooks === 0) {
        return res.json({
          success: true,
          data: {
            totalBooks: 0,
            averageRating: 0,
            genreDistribution: {},
            oldestPublicationYear: null,
            newestPublicationYear: null,
          },
        });
      }

      // Compute average rating.
      const sumRatings = books.reduce((acc, b) => acc + b.rating, 0);
      const averageRating = parseFloat((sumRatings / totalBooks).toFixed(2));

      // Build genre distribution map.
      const genreDistribution = {};
      for (const book of books) {
        genreDistribution[book.genre] = (genreDistribution[book.genre] || 0) + 1;
      }

      // Find min/max publication years.
      const years = books.map((b) => b.publishedYear);
      const oldestPublicationYear = Math.min(...years);
      const newestPublicationYear = Math.max(...years);

      res.json({
        success: true,
        data: {
          totalBooks,
          averageRating,
          genreDistribution,
          oldestPublicationYear,
          newestPublicationYear,
        },
      });
    } catch (err) {
      next(err);
    }
  });

  return router;
};

module.exports = createStatsRoutes;
```

