## File 5 — `server.js`

```javascript
/**
 * Main entry point for the Book REST API.
 *
 * WHY this structure?
 *   - server.js is responsible ONLY for:
 *       1. Loading dependencies.
 *       2. Configuring middleware (CORS, helmet, JSON parsing).
 *       3. Mounting route handlers.
 *       4. Starting the HTTP server on a port.
 *   - Business logic lives in routes/ and middleware/, keeping this file thin.
 *
 * WHY async/await throughout?
 *   - Even though our current store is synchronous (in-memory array), using async functions
 *     prepares the code for future database integration where operations ARE asynchronous.
 *   - It avoids callback hell and makes error handling with try/catch natural.
 */

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');

// Import our custom error handler middleware (must be registered LAST).
const { errorHandler } = require('./middleware/errorHandler');

// Import route creators.
const createBookRoutes = require('./routes/books');
const createStatsRoutes = require('./routes/stats');

// ---------------------------------------------------------------------------
// App initialization
// ---------------------------------------------------------------------------

/**
 * Create the Express application instance.
 */
const app = express();

// ---------------------------------------------------------------------------
// Middleware stack (order matters!)
// ---------------------------------------------------------------------------

/**
 * helmet: Sets security-related HTTP headers (X-Content-Type-Options, X-Frame-Options, etc.).
 *          Protects against common web vulnerabilities like XSS and clickjacking.
 */
app.use(helmet());

/**
 * cors: Enables Cross-Origin Resource Sharing.
 *       Allows browsers on different origins to call this API (useful for frontend dev).
 */
app.use(cors());

/**
 * express.json(): Parses incoming request bodies with JSON format.
 *                  Populates req.body so route handlers can read POST/PUT payloads.
 */
app.use(express.json());

// ---------------------------------------------------------------------------
// Route mounting
// ---------------------------------------------------------------------------

/**
 * Mount the book CRUD routes under /books.
 * All endpoints defined in routes/books.js become available at /books, /books/:id, etc.
 */
app.use('/books', createBookRoutes());

/**
 * Mount the stats route under /stats.
 */
app.use('/stats', createStatsRoutes());

// ---------------------------------------------------------------------------
// Root endpoint (health check)
// ---------------------------------------------------------------------------

/**
 * @name GET /
 * @description Simple health-check endpoint to verify the server is running.
 * @returns {object} 200 — { success: true, message: 'Book API is running' }
 * @example curl http://localhost:3000/
 */
app.get('/', (req, res) => {
  res.json({ success: true, message: 'Book API is running' });
});

// ---------------------------------------------------------------------------
// Global error-handling middleware (MUST be last)
// ---------------------------------------------------------------------------

/**
 * Express calls this function whenever next(err) is invoked upstream.
 * It catches all errors — both our custom AppError instances and unexpected exceptions.
 */
app.use(errorHandler);

// ---------------------------------------------------------------------------
// 404 handler for undefined routes
// ---------------------------------------------------------------------------

/**
 * If a request reaches here, no route matched. Return 404 with a JSON body.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Route ${req.method} ${req.path} not found`,
      type: 'NotFoundError',
    },
  });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

/**
 * Start the HTTP server and listen on the configured port.
 * Defaults to 3000; can be overridden via the PORT environment variable.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Health check: GET http://localhost:${PORT}/`);
  console.log(`   Books:        GET/POST http://localhost:${PORT}/books`);
  console.log(`   Stats:        GET http://localhost:${PORT}/stats`);
});

module.exports = app;
```

