## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: book.js — Modelo de Dados (Camada de Dados)
 * ============================================================
 *
 * POR QUE UM ARQUIVO SEPARADO PARA O MODELO?
 * -------------------------------------------
 * A separação entre rotas e modelo segue o padrão MVC (Model-View-Controller).
 * As rotas sabem COMO responder às requisições HTTP, mas não devem saber
 * COMO os dados são armazenados ou manipulados. Isso permite:
 *   1. Trocar o armazenamento (array → banco de dados) sem alterar as rotas.
 *   2. Reutilizar a lógica de negócio em diferentes contextos.
 *   3. Testar a lógica de dados independentemente da camada HTTP.
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * --------------------------
 * Para um exemplo educacional, arrays são ideais porque:
 *   - Não requerem instalação de banco de dados.
 *   - São simples de entender e depurar.
 *   - Permitem focar nos conceitos de REST sem distrações.
 * Em produção, substituiríamos por MongoDB, PostgreSQL, etc.
 */

// ============================================================
//  ESTRUTURA DE DADOS: Array em memória com objetos Livro
// ============================================================
//
// Cada livro é um objeto com as seguintes propriedades:
//   - id       (number): Identificador único autoincremental.
//                        Usamos number em vez de string/UUID porque:
//                          • É mais simples para exemplos educacionais.
//                          • Facilita a filtragem e ordenação numérica.
//                          • Em bancos relacionais, INT é o padrão natural.
//   - title    (string): Título do livro — obrigatório.
//   - author   (string): Autor do livro — obrigatório.
//   - year     (number): Ano de publicação — opcional, mas recomendado.
//   - genre    (string): Gênero literário — opcional.
//   - createdAt (string): Timestamp ISO 8601 da criação (gerado automaticamente).
//   - updatedAt (string): Timestamp ISO 8601 da última atualização.
//
// Usamos um array porque:
//   - A ordem de inserção é preservada (comportamento natural do JS).
//   - Operações como map/filter/reduce são nativas e eficientes para pequenos conjuntos.
//   - Não há necessidade de índices complexos em dados de exemplo.

/** @type {Array<Object>} Lista de livros armazenados em memória */
const books = [];

/** @type {number} Contador autoincremental para geração de IDs únicos */
let nextId = 1;

// ============================================================
//  CLASSE DE ERRO PERSONALIZADA: BookNotFoundError
// ============================================================
//
// POR QUE UMA CLASSE DE ERRO CUSTOMIZADA?
// ----------------------------------------
// Erros personalizados permitem:
//   1. Identificar o tipo de erro com instanceof.
//   2. Adicionar propriedades específicas (ex: id do recurso não encontrado).
//   3. Melhorar a experiência de depuração e tratamento de erros.
//
// Herdamos de Error para manter compatibilidade com o ecossistema Node.js,
// mas sobrescrevemos o nome da classe para facilitar a identificação.

class BookNotFoundError extends Error {
  /**
   * @param {number} id - O ID do livro que não foi encontrado.
   */
  constructor(id) {
    // super() chama o construtor da classe pai (Error), definindo message e stack.
    super(`Livro com ID ${id} não encontrado`);
    this.name = 'BookNotFoundError';
    this.statusCode = 404; // Código HTTP padrão para "não encontrado"
    this.id = id;          // Propriedade extra para uso no middleware de erro
  }
}

// ============================================================
//  FUNÇÕES DO MODELO (Camada de Dados)
// ============================================================

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista completa de livros.
 *
 * NOTA: Retornamos uma cópia rasa do array ([...books]) para evitar que
 * chamadores externos modifiquem o array original diretamente. Isso preserva
 * a encapsulação dos dados — a única forma de modificá-los é através das
 * funções fornecidas por este módulo.
 */
function findAll() {
  return [...books];
}

/**
 * Busca um livro pelo seu ID.
 *
 * @param {number} id - O identificador único do livro.
 * @returns {Object|null} O livro encontrado ou null se não existir.
 *
 * Usamos Array.prototype.find() em vez de filter()[0] porque:
 *   - find() para na primeira correspondência (mais eficiente).
 *   - Retorna null explicitamente quando nada é encontrado (sem erro).
 */
function findById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} data - Dados do livro a ser criado.
 * @param {string} data.title - Título do livro (obrigatório).
 * @param {string} data.author - Autor do livro (obrigatório).
 * @param {number} [data.year] - Ano de publicação (opcional).
 * @param {string} [data.genre] - Gênero literário (opcional).
 * @returns {Object} O livro criado com ID e timestamps gerados automaticamente.
 *
 * POR QUE USAR SPREAD OPERATOR ({ ...data })?
 * -------------------------------------------
 * Criamos uma cópia dos dados de entrada para:
 *   1. Não mutar o objeto original passado pelo chamador (imutabilidade).
 *   2. Adicionar campos calculados (id, timestamps) sem afetar a fonte.
 */
function create(data) {
  const now = new Date().toISOString(); // ISO 8601: formato padrão da indústria

  const book = {
    id: nextId++,                          // Autoincremento simples e previsível
    title: data.title,
    author: data.author,
    year: data.year ?? null,               // Nullish coalescing: usa null se undefined/null
    genre: data.genre ?? null,
    createdAt: now,
    updatedAt: now,
  };

  books.push(book); // push() retorna o novo comprimento, mas nos interessa o book
  return { ...book }; // Retorna cópia para evitar mutação externa
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - Identificador do livro a atualizar.
 * @param {Object} updates - Campos a serem atualizados (parcial).
 * @returns {Object} O livro atualizado.
 * @throws {BookNotFoundError} Se o livro com o ID não existir.
 *
 * POR QUE ATUALIZAÇÃO PARCIAL (PATCH-style) VIA PUT?
 * --------------------------------------------------
 * Em REST, PUT deve substituir o recurso inteiro, mas na prática muitos
 * frameworks aceitam atualização parcial. Para este exemplo educacional,
 * usamos atualização parcial porque:
 *   - É mais flexível para testes.
 *   - O cliente não precisa enviar todos os campos a cada requisição.
 * Em produção com PUT verdadeiro, retornaríamos 400 se campos obrigatórios
 * faltarem, ou usaríamos PATCH para atualizações parciais.
 */
function update(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    // Lançamos a exceção personalizada para que o middleware de erro a capture.
    throw new BookNotFoundError(id);
  }

  // Atualiza apenas os campos fornecidos, preservando os demais.
  // O operador spread cria um novo objeto sem mutar o original no array.
  const updatedBook = {
    ...books[index],                       // Copia todos os campos existentes
    ...updates,                            // Sobrescreve com os novos valores
    id: books[index].id,                   // Garante que o ID não seja alterado
    createdAt: books[index].createdAt,     // Timestamp de criação é imutável
    updatedAt: new Date().toISOString(),   // Atualiza timestamp de modificação
  };

  books[index] = updatedBook; // Substitui no array (operação O(1) por índice)
  return { ...updatedBook };
}

/**
 * Exclui um livro pelo ID.
 *
 * @param {number} id - Identificador do livro a excluir.
 * @returns {boolean} true se excluído com sucesso, false caso contrário.
 * @throws {BookNotFoundError} Se o livro com o ID não existir.
 *
 * Usamos findIndex() + splice() em vez de filter() porque:
 *   - splice() modifica o array original in-place (mais eficiente para arrays pequenos).
 *   - filter() criaria um novo array a cada exclusão (desperdício de memória).
 */
function remove(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    throw new BookNotFoundError(id);
  }

  books.splice(index, 1); // Remove 1 elemento na posição index
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas incluindo total, média de anos, gêneros e autores.
 *
 * Usamos Array.prototype.reduce() para calcular múltiplas métricas em uma única
 * passagem pelo array — isso é O(n) em vez de O(n*k) onde k é o número de métricas.
 */
function getStats() {
  if (books.length === 0) {
    return {
      total: 0,
      averageYear: null,
      genres: {},
      authors: [],
    };
  }

  const stats = books.reduce(
    (acc, book) => {
      acc.total += 1;
      if (book.year !== null && book.year !== undefined) {
        acc.sumYear += book.year;
        acc.yearsCount += 1;
      }
      // Conta gêneros usando um objeto como mapa de frequência
      if (book.genre) {
        acc.genres[book.genre] = (acc.genres[book.genre] || 0) + 1;
      }
      // Coleciona autores únicos
      if (!acc.authors.includes(book.author)) {
        acc.authors.push(book.author);
      }
      return acc;
    },
    { total: 0, sumYear: 0, yearsCount: 0, genres: {}, authors: [] }
  );

  return {
    total: stats.total,
    averageYear: stats.yearsCount > 0
      ? Math.round(stats.sumYear / stats.yearsCount) // Arredonda para inteiro
      : null,
    genres: stats.genres,
    authors: stats.authors.sort(), // Ordena alfabeticamente para consistência
  };
}

// ============================================================
//  EXPORTAÇÃO DE MÓDULO (CommonJS)
// ============================================================
//
// Usamos module.exports em vez de export default porque:
//   - CommonJS é o padrão nativo do Node.js (sem necessidade de transpilers).
//   - É mais simples para exemplos educacionais.
//   - Funciona com qualquer versão do Node.js sem configuração adicional.

module.exports = {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats,
  BookNotFoundError, // Exportamos a classe de erro para uso no middleware
};
