## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: errorHandler.js — Middleware de Tratamento de Erros
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE DE ERROS SEPARADO?
 * -----------------------------------------
 * Em Express, o middleware de erro é uma função com 4 parâmetros:
 *   (error, req, res, next) => { ... }
 *
 * Express identifica automaticamente funções de erro pelo número de parâmetros.
 * Centralizar o tratamento de erros permite:
 *   1. Respostas de erro consistentes em toda a API.
 *   2. Logs centralizados para monitoramento.
 *   3. Separação clara entre lógica de negócio e lógica de apresentação.
 *
 * A ordem importa: este middleware DEVE ser registrado APÓS todas as rotas,
 * caso contrário ele capturaria requisições normais como erros.
 */

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} error - O erro lançado por uma rota ou middleware anterior.
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware.
 *
 * ESTRATÉGIA DE TRATAMENTO:
 * -------------------------
 * 1. Verificamos se é um erro conhecido (BookNotFoundError) → respondemos com seu statusCode.
 * 2. Para erros desconhecidos, usamos 500 Internal Server Error como fallback seguro.
 * 3. Sempre retornamos JSON para manter a consistência da API.
 * 4. Em desenvolvimento, incluímos o stack trace para facilitar a depuração.
 */
function errorHandler(error, req, res, next) {
  // Determina o código de status com base no tipo de erro
  const statusCode = error.statusCode || 500;

  // Em desenvolvimento, enviamos o stack trace para ajudar na depuração.
  // Em produção, isso seria um risco de segurança (vazamento de informações internas).
  const isDevelopment = process.env.NODE_ENV !== 'production';

  const response = {
    success: false,
    error: {
      message: error.message || 'Erro interno do servidor',
      ...(isDevelopment && { stack: error.stack }), // Spread condicional: só em dev
    },
    timestamp: new Date().toISOString(), // Timestamp da ocorrência do erro
  };

  // Se for um erro de livro não encontrado, incluímos o ID para facilitar debugging
  if (error.name === 'BookNotFoundError') {
    response.error.id = error.id;
  }

  console.error(`[ERROR] ${statusCode} - ${error.message}`);
  if (isDevelopment && error.stack) {
    console.error(error.stack);
  }

  res.status(statusCode).json(response);
}

/**
 * Middleware para lidar com rotas não encontradas (404).
 *
 * Este middleware é registrado APÓS todas as rotas. Se nenhuma rota corresponder,
 * o Express continua a execução e atinge este middleware, que responde com 404.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFoundHandler(req, res, next) {
  // Chama o errorHandler com um erro 404 genérico.
  // Isso reutiliza a lógica de formatação de resposta sem duplicação de código.
  const error = new Error(`Rota não encontrada: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
}

module.exports = { errorHandler, notFoundHandler };
```

