## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: books.js — Rotas da API de Livros
 * ============================================================
 *
 * POR QUE UM ARQUIVO DE ROTAS SEPARADO?
 * -------------------------------------
 * Manter as rotas em um arquivo separado permite:
 *   - Escalar o projeto adicionando mais arquivos de rota (ex: /authors, /reviews).
 *   - Testar rotas isoladamente.
 *   - Manter o app.js principal limpo e focado na configuração.
 *
 * PADRÃO REST ADOTADO:
 * --------------------
 * | Método HTTP | Endpoint       | Ação                    | Código de Retorno      |
 * |-------------|----------------|-------------------------|------------------------|
 * | GET         | /books         | Listar todos            | 200 OK                 |
 * | GET         | /books/:id     | Buscar por ID           | 200 OK / 404 Not Found |
 * | POST        | /books         | Criar novo              | 201 Created            |
 * | PUT         | /books/:id     | Atualizar completo      | 200 OK / 404 Not Found |
 * | DELETE      | /books/:id     | Excluir                 | 200 OK / 404 Not Found |
 * | GET         | /stats         | Estatísticas            | 200 OK                 |
 *
 * CONVENÇÕES REST SEGUIDAS:
 * --------------------------
 * 1. Nomes de recursos no plural (/books, não /book) — indica coleção.
 * 2. IDs como parâmetros de caminho (:id), não query params — mais semântico.
 * 3. Métodos HTTP corretos para cada operação (GET=read, POST=create, etc.).
 * 4. Respostas em JSON com campo "success" para consistência.
 * 5. Códigos de status HTTP apropriados (201 para criação, 404 para não encontrado).
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente
const {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats,
  BookNotFoundError,
} = require('../models/book');

// ============================================================
//  VALIDAÇÃO DE ENTRADA (Input Validation)
// ============================================================
//
// POR QUE VALIDAR ENTRADAS?
// -------------------------
// Validação protege contra:
//   - Dados malformados que poderiam causar erros no servidor.
//   - Injeção de dados maliciosos (embora aqui seja em memória, é boa prática).
//   - Campos obrigatórios ausentes que quebrariam a lógica de negócio.
//
// Em um projeto real, usaríamos bibliotecas como Joi, Zod ou express-validator.

/**
 * Valida os campos obrigatórios para criação/atualização de livro.
 *
 * @param {Object} body - Corpo da requisição.
 * @returns {string|null} Mensagem de erro ou null se válido.
 */
function validateBookInput(body) {
  if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
    return 'O campo "title" é obrigatório e deve ser uma string não vazia.';
  }
  if (!body.author || typeof body.author !== 'string' || body.author.trim() === '') {
    return 'O campo "author" é obrigatório e deve ser uma string não vazia.';
  }
  if (body.year !== undefined && body.year !== null) {
    const year = Number(body.year);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      return 'O campo "year" deve ser um número inteiro válido.';
    }
  }
  return null; // Null indica que a validação passou
}

/**
 * Valida se o ID é um número inteiro positivo.
 *
 * @param {*} id - O valor do parâmetro de rota.
 * @returns {string|null} Mensagem de erro ou null se válido.
 */
function validateId(id) {
  const num = Number(id);
  if (!Number.isInteger(num) || num < 1) {
    return 'O ID deve ser um número inteiro positivo.';
  }
  return null;
}

// ============================================================
//  GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================
//
 * Exemplo curl:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Ficção"
 *   curl "http://localhost:3000/books?author=Clarice+Lispector"
 *   curl "http://localhost:3000/books?year=2000"
 *
 * Exemplo Postman:
 *   Method: GET
 *   URL: http://localhost:3000/books?genre=Ficção&author=Clarice+Lispector
 */
router.get('/books', (req, res) => {
  try {
    let result = findAll(); // Começa com todos os livros

    // Filtragem por gênero (case-insensitive para melhor UX)
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(book => book.genre?.toLowerCase() === genreFilter);
    }

    // Filtragem por autor (parcial, case-insensitive)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // Filtragem por ano (igualdade exata)
    if (req.query.year) {
      const yearFilter = Number(req.query.year);
      result = result.filter(book => book.year === yearFilter);
    }

    res.json({
      success: true,
      count: result.length,           // Número de livros na resposta filtrada
      data: result,                   // Lista de livros
      message: result.length === 0
        ? 'Nenhum livro encontrado.'
        : `${result.length} livro(s) encontrado(s).`,
    });
  } catch (error) {
    next(error); // Passa o erro para o middleware de tratamento
  }
});

// ============================================================
//  GET /books/stats — Estatísticas dos livros
// ============================================================
//
 * Exemplo curl:
 *   curl http://localhost:3000/stats
 *
 * Exemplo Postman:
 *   Method: GET
 *   URL: http://localhost:3000/stats
 */
router.get('/stats', (req, res) => {
  try {
    const stats = getStats();
    res.json({
      success: true,
      data: stats,
      message: 'Estatísticas calculadas com sucesso.',
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  GET /books/:id — Obter livro por ID
// ============================================================
//
 * Exemplo curl:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404
 *
 * Exemplo Postman:
 *   Method: GET
 *   URL: http://localhost:3000/books/1
 */
router.get('/books/:id', (req, res) => {
  try {
    const idError = validateId(req.params.id);
    if (idError) {
      return res.status(400).json({
        success: false,
        error: { message: idError },
      });
    }

    const id = Number(req.params.id);
    const book = findById(id);

    if (!book) {
      // Em vez de lançar exceção, respondemos diretamente com 404.
      // Isso é aceitável em rotas simples; em projetos maiores, usaríamos o modelo.
      return res.status(404).json({
        success: false,
        error: { message: `Livro com ID ${id} não encontrado.` },
      });
    }

    res.json({
      success: true,
      data: book,
      message: 'Livro encontrado.',
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  POST /books — Criar novo livro
// ============================================================
//
 * Exemplo curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899,"genre":"Romance"}'
 *
 * Exemplo Postman:
 *   Method: POST
 *   URL: http://localhost:3000/books
 *   Headers: Content-Type: application/json
 *   Body (raw JSON):
 *   {
 *     "title": "Dom Casmurro",
 *     "author": "Machado de Assis",
 *     "year": 1899,
 *     "genre": "Romance"
 *   }
 */
router.post('/books', (req, res) => {
  try {
    const validationError = validateBookInput(req.body);
    if (validationError) {
      return res.status(400).json({
        success: false,
        error: { message: validationError },
      });
    }

    const book = create(req.body);

    // 201 Created é o código HTTP padrão para recursos criados com sucesso.
    // Diferente de 200 OK, ele indica que uma nova resource foi criada.
    res.status(201).json({
      success: true,
      data: book,
      message: 'Livro criado com sucesso.',
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
//  PUT /books/:id — Atualizar livro existente
// ============================================================
//
 * Exemplo curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Atualizada)","year":2020}'
 *
 * Exemplo Postman:
 *   Method: PUT
 *   URL: http://localhost:3000/books/1
 *   Headers: Content-Type: application/json
 *   Body (raw JSON):
 *   {
 *     "title": "Dom Casmurro (Ed. Atualizada)",
 *     "year": 2020
 *   }
 */
router.put('/books/:id', (req, res) => {
  try {
    const idError = validateId(req.params.id);
    if (idError) {
      return res.status(400).json({
        success: false,
        error: { message: idError },
      });
    }

    const validationError = validateBookInput(req.body);
    if (validationError) {
      return res.status(400).json({
        success: false,
        error: { message: validationError },
      });
    }

    const id = Number(req.params.id);
    const book = update(id, req.body);

    res.json({
      success: true,
      data: book,
      message: 'Livro atualizado com sucesso.',
    });
  } catch (error) {
    if (error instanceof BookNotFoundError) {
      return res.status(404).json({
        success: false,
        error: { message: error.message },
      });
    }
    next(error);
  }
});

// ============================================================
//  DELETE /books/:id — Excluir livro
// ============================================================
//
 * Exemplo curl:
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * Exemplo Postman:
 *   Method: DELETE
 *   URL: http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res) => {
  try {
    const idError = validateId(req.params.id);
    if (idError) {
      return res.status(400).json({
        success: false,
        error: { message: idError },
      });
    }

    const id = Number(req.params.id);
    remove(id);

    // 200 OK com mensagem de confirmação. Alguns frameworks usam 204 No Content
    // (sem body) para DELETE, mas incluir uma resposta facilita o debugging.
    res.json({
      success: true,
      message: `Livro com ID ${id} excluído com sucesso.`,
    });
  } catch (error) {
    if (error instanceof BookNotFoundError) {
      return res.status(404).json({
        success: false,
        error: { message: error.message },
      });
    }
    next(error);
  }
});

module.exports = router;
```

