## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: app.js — Configuração da Aplicação Express
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * app.js configura a aplicação (middleware, rotas, etc.).
 * server.js apenas inicia o servidor HTTP.
 * Essa separação permite:
 *   - Testar a configuração da app sem precisar de um servidor rodando.
 *   - Reutilizar a mesma app em testes automatizados.
 *   - Manter o código mais organizado e testável.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler, notFoundHandler } = require('./middleware/errorHandler');

const app = express(); // Cria a instância da aplicação Express

// ============================================================
//  MIDDLEWARE GLOBAL (Aplicado a TODAS as requisições)
// ============================================================
//
 * POR QUE USAR MIDDLEWARE?
 * ------------------------
 * Middleware são funções que têm acesso ao objeto req, res e next.
 * Eles executam em sequência, permitindo:
 *   1. Transformar dados antes das rotas (ex: parse de JSON).
 *   2. Adicionar headers globais (ex: CORS, segurança).
 *   3. Log de requisições para monitoramento.
 *   4. Autenticação e autorização.

/**
 * Middleware para fazer parse do corpo das requisições JSON.
 * Express 4.x não faz isso automaticamente — precisamos do body-parser.
 * O express.json() interno já embutido no Express resolve isso.
 */
app.use(express.json()); // Parse automaticamente req.body a partir de JSON

/**
 * Middleware para fazer parse de URLs codificadas (query strings).
 * Habilita acesso a valores numéricos em query params via Number().
 */
app.use(express.urlencoded({ extended: true }));

/**
 * Middleware de logging simples para depuração.
 * Imprime método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next(); // SEMPRE chame next() para passar ao próximo middleware/rota
});

// ============================================================
//  REGISTRO DE ROTAS
// ============================================================
//
 * POR QUE app.use('/api', router)?
 * --------------------------------
 * O prefixo '/api' cria um namespace que permite:
 *   - Adicionar versões futuras (/api/v2) sem quebrar clientes existentes.
 *   - Diferenciar rotas da API de outras rotas (ex: /health, /docs).
 *   - Seguir a convenção REST de namespacing de APIs.

app.use('/api', bookRoutes); // Todas as rotas em ./routes/books.js ficam sob /api

// ============================================================
//  MIDDLEWARE DE ERROS (DEVE SEMPRE VIR POR ÚLTIMO)
// ============================================================
//
 * ORDEM IMPORTA! Os middlewares de erro devem ser registrados APÓS todas as rotas.
 * Se colocados antes, eles capturariam requisições normais como erros.
 * Express percorre os middlewares em ordem e para no primeiro que responde.

app.use(notFoundHandler);   // Captura rotas não encontradas (404)
app.use(errorHandler);      // Captura todos os outros erros (500, etc.)

module.exports = app; // Exportamos para que server.js possa usar
```

