## File 2: `server.js` — Entry Point & App Setup

```javascript
/**
 * server.js — Application entry point
 *
 * This file bootstraps the Express application, configures middleware,
 * mounts route handlers, and starts the HTTP server on port 3000.
 *
 * Architecture decisions:
 * - We use express.json() to parse incoming JSON request bodies (required for POST/PUT).
 * - Routes are mounted under /api so the API namespace is clear (/api/books, /api/stats).
 * - A global error-handling middleware catches any unhandled errors and returns a consistent JSON response.
 */

const express = require('express');

// Import route handlers (defined in routes.js)
const bookRoutes = require('./routes');

// Create the Express application instance
const app = express();

// ──────────────────────────────────────────────
// Middleware Configuration
// ──────────────────────────────────────────────

/**
 * express.json() — Parses incoming requests with JSON payloads.
 * Without this, req.body would be undefined for POST/PUT requests.
 */
app.use(express.json());

/**
 * Simple request logger middleware.
 * Logs the HTTP method, URL, and timestamp for every request.
 * Useful for debugging and understanding request flow.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ──────────────────────────────────────────────
// Route Mounting
// ──────────────────────────────────────────────

/**
 * Mount all book-related routes under /api/books.
 * The route file exports an Express Router, which we attach here.
 */
app.use('/api/books', bookRoutes);

/**
 * GET /api/stats — Returns aggregate statistics about the book collection.
 * Kept separate from the books router for clarity.
 */
app.get('/api/stats', (req, res) => {
  // Import the stats function from our data layer
  const { getStats } = require('./data');
  const stats = getStats();

  /**
   * Respond with a JSON object containing:
   * - totalBooks: number of books in the collection
   * - averageRating: mean rating across all books (rounded to 2 decimals)
   * - genres: count of books per genre
   */
  res.json({
    success: true,
    data: stats
  });
});

// ──────────────────────────────────────────────
// Global Error-Handling Middleware
// ──────────────────────────────────────────────

/**
 * Express error-handling middleware (4-parameter signature).
 * This catches any errors thrown in route handlers or middleware.
 * It ensures we never return a raw stack trace to the client.
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);

  // Default to 500 Internal Server Error if no status is set
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    success: false,
    error: err.message
  });
});

// ──────────────────────────────────────────────
// Start the Server
// ──────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: GET  http://localhost:${PORT}/api/books`);
  console.log(`        POST http://localhost:${PORT}/api/books`);
  console.log(`        GET  http://localhost:${PORT}/api/stats`);
});
```

> **Why mount routes under `/api/`?** This is a common convention that separates API endpoints from potential static files or other server routes. It also makes it easy to version later (`/api/v1/books`).

