## File 3: `data.js` — In-Memory Data Store & Business Logic

```javascript
/**
 * data.js — In-memory data store and business logic layer
 *
 * We use a plain JavaScript array to simulate a database.
 * Each book is an object with the following shape:
 *   {
 *     id: number,          // Unique identifier (auto-increment)
 *     title: string,       // Book title
 *     author: string,      // Author name
 *     genre: string,       // Genre/category (e.g., "Fiction", "Science")
 *     publishedYear: number, // Year of publication
 *     rating: number       // Average rating from 1-5
 *   }
 *
 * Why an array? For this educational example, arrays are simple and fast.
 * In production, you'd replace this with a database (PostgreSQL, MongoDB, etc.).
 */

// ──────────────────────────────────────────────
// Initial Seed Data
// ──────────────────────────────────────────────

/**
 * Pre-populate the store with sample books so the API isn't empty on startup.
 */
let books = [
  { id: 1, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
  { id: 2, title: 'A Brief History of Time', author: 'Stephen Hawking', genre: 'Science', publishedYear: 1988, rating: 4.6 },
  { id: 3, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 4, title: 'Clean Code', author: 'Robert C. Martin', genre: 'Technology', publishedYear: 2008, rating: 4.7 },
  { id: 5, title: 'Dune', author: 'Frank Herbert', genre: 'Science Fiction', publishedYear: 1965, rating: 4.9 }
];

/**
 * Auto-incrementing ID counter.
 * In a real database, this would be handled by an auto-increment column or UUID generator.
 */
let nextId = 6;

// ──────────────────────────────────────────────
// Data Access Functions
// ──────────────────────────────────────────────

/**
 * getAllBooks — Retrieve all books, optionally filtered.
 *
 * @param {Object} filters - Optional query parameters:
 *   - genre: string       Filter by exact genre match (case-insensitive)
 *   - minRating: number   Minimum rating threshold (1-5)
 *
 * @returns {Array<Object>} Array of book objects matching the criteria
 *
 * Example usage:
 *   getAllBooks({ genre: 'Fiction' })       → returns only Fiction books
 *   getAllBooks({ minRating: 4.5 })         → returns books with rating >= 4.5
 *   getAllBooks({ genre: 'Science', minRating: 4.0 }) → both filters applied
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Create a shallow copy to avoid mutating the original array

  // Apply genre filter if provided (case-insensitive comparison)
  if (filters.genre) {
    const normalizedGenre = filters.genre.toLowerCase();
    result = result.filter(book => book.genre.toLowerCase() === normalizedGenre);
  }

  // Apply minimum rating filter if provided
  if (filters.minRating !== undefined && filters.minRating !== null) {
    const minRating = parseFloat(filters.minRating);
    result = result.filter(book => book.rating >= minRating);
  }

  return result;
}

/**
 * getBookById — Find a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * createBook — Add a new book to the collection.
 *
 * @param {Object} bookData - Partial book object (id is auto-generated)
 * @returns {Object} The newly created book with its assigned ID
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Assign and increment the ID counter
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre,
    publishedYear: bookData.publishedYear,
    rating: bookData.rating || 0 // Default to 0 if not provided
  };

  books.push(newBook);
  return newBook;
}

/**
 * updateBook — Replace an existing book with updated data.
 *
 * @param {number} id - The ID of the book to update
 * @param {Object} updates - Fields to update (partial object)
 * @returns {Object|null} The updated book, or null if not found
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return null; // Book not found
  }

  // Merge existing data with updates (spread operator creates a new object)
  const updatedBook = { ...books[index], ...updates, id };
  books[index] = updatedBook;

  return updatedBook;
}

/**
 * deleteBook — Remove a book from the collection by ID.
 *
 * @param {number} id - The ID of the book to delete
 * @returns {boolean} true if deleted, false if not found
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false;
  }

  books.splice(index, 1); // Remove the book from the array
  return true;
}

/**
 * getStats — Compute aggregate statistics about the book collection.
 *
 * @returns {Object} Statistics including:
 *   - totalBooks: number of books
 *   - averageRating: mean rating (rounded to 2 decimals)
 *   - genres: object mapping genre names to book counts
 */
function getStats() {
  const totalBooks = books.length;

  // Calculate average rating, handling empty array edge case
  const averageRating = totalBooks > 0
    ? parseFloat((books.reduce((sum, b) => sum + b.rating, 0) / totalBooks).toFixed(2))
    : 0;

  // Count books per genre using reduce
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  return { totalBooks, averageRating, genres };
}

// ──────────────────────────────────────────────
// Module Exports
// ──────────────────────────────────────────────

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

> **Why separate `data.js` from routes?** This follows the *separation of concerns* principle. Routes handle HTTP concerns (status codes, headers), while data functions handle business logic. This makes testing and future database swaps much easier.

