## File 4: `routes.js` — Express Route Handlers

```javascript
/**
 * routes.js — Express route handlers for /api/books
 *
 * Each handler follows this pattern:
 *   1. Extract input from req (params, query, body)
 *   2. Validate input
 *   3. Call the data layer function
 *   4. Return an appropriate HTTP response with status code
 *
 * HTTP Status Code Reference:
 *   200 OK          — Successful GET/PUT
 *   201 Created     — Successful POST (resource created)
 *   204 No Content  — Successful DELETE (no body to return)
 *   400 Bad Request — Client sent invalid input
 *   404 Not Found   — Resource doesn't exist
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance

// Import data layer functions
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('./data');

// ──────────────────────────────────────────────
// GET /api/books — List all books (with optional filtering)
// ──────────────────────────────────────────────

/**
 * @route   GET /api/books
 * @desc    Retrieve a list of books, optionally filtered by genre or minimum rating
 * @access  Public
 *
 * Query Parameters:
 *   - genre     (string)  Filter by exact genre match (case-insensitive)
 *   - minRating (number)  Minimum rating threshold (1-5)
 *
 * Example curl commands:
 *   # Get all books
 *   curl http://localhost:3000/api/books
 *
 *   # Filter by genre
 *   curl "http://localhost:3000/api/books?genre=Fiction"
 *
 *   # Filter by minimum rating
 *   curl "http://localhost:3000/api/books?minRating=4.5"
 *
 *   # Combine filters
 *   curl "http://localhost:3000/api/books?genre=Science&minRating=4.0"
 */
router.get('/', (req, res) => {
  // Extract optional query parameters
  const { genre, minRating } = req.query;

  // Build the filters object — only include keys that have values
  const filters = {};
  if (genre) filters.genre = genre;
  if (minRating) filters.minRating = minRating;

  // Call the data layer
  const result = getAllBooks(filters);

  /**
   * Return 200 OK with the filtered book list.
   * We wrap it in { success: true, data: ... } for a consistent API response shape.
   */
  res.json({ success: true, data: result });
});

// ──────────────────────────────────────────────
// GET /api/books/:id — Get a single book by ID
// ──────────────────────────────────────────────

/**
 * @route   GET /api/books/:id
 * @desc    Retrieve a single book by its numeric ID
 * @access  Public
 *
 * Path Parameters:
 *   - id (number) — The unique identifier of the book
 *
 * Example curl commands:
 *   # Get book with ID 1
 *   curl http://localhost:3000/api/books/1
 *
 *   # Try a non-existent ID (returns 404)
 *   curl http://localhost:3000/api/books/999
 */
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10); // Convert string param to integer

  // Validate that the ID is a valid number
  if (isNaN(id)) {
    return res.status(400).json({ success: false, error: 'Invalid book ID. Must be a number.' });
  }

  const book = getBookById(id);

  if (!book) {
    // Return 404 Not Found when the resource doesn't exist
    return res.status(404).json({ success: false, error: `Book with ID ${id} not found.` });
  }

  res.json({ success: true, data: book });
});

// ──────────────────────────────────────────────
// POST /api/books — Create a new book
// ──────────────────────────────────────────────

/**
 * @route   POST /api/books
 * @desc    Create a new book in the collection
 * @access  Public
 *
 * Request Body (JSON):
 *   {
 *     "title": "The Hobbit",
 *     "author": "J.R.R. Tolkien",
 *     "genre": "Fantasy",
 *     "publishedYear": 1937,
 *     "rating": 4.7
 *   }
 *
 * All fields except rating are required. Rating defaults to 0 if omitted.
 *
 * Example curl command:
 *   curl -X POST http://localhost:3000/api/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Hobbit","author":"J.R.R. Tolkien","genre":"Fantasy","publishedYear":1937,"rating":4.7}'
 */
router.post('/', (req, res) => {
  const { title, author, genre, publishedYear, rating } = req.body;

  // Validate required fields
  if (!title || !author || !genre || !publishedYear) {
    return res.status(400).json({
      success: false,
      error: 'Missing required fields: title, author, genre, and publishedYear are required.'
    });
  }

  // Validate publishedYear is a reasonable number
  if (typeof publishedYear !== 'number' || publishedYear < 1000 || publishedYear > new Date().getFullYear() + 1) {
    return res.status(400).json({
      success: false,
      error: 'publishedYear must be a number between 1000 and the current year + 1.'
    });
  }

  // Validate rating if provided
  if (rating !== undefined && (typeof rating !== 'number' || rating < 0 || rating > 5)) {
    return res.status(400).json({
      success: false,
      error: 'rating must be a number between 0 and 5.'
    });
  }

  // Create the book via the data layer
  const newBook = createBook({ title, author, genre, publishedYear, rating });

  /**
   * Return 201 Created with the newly created book.
   * 201 is the standard status code for successful resource creation.
   */
  res.status(201).json({ success: true, data: newBook });
});

// ──────────────────────────────────────────────
// PUT /api/books/:id — Update an existing book
// ──────────────────────────────────────────────

/**
 * @route   PUT /api/books/:id
 * @desc    Fully replace an existing book's data
 * @access  Public
 *
 * Path Parameters:
 *   - id (number) — The unique identifier of the book to update
 *
 * Request Body (JSON):
 *   {
 *     "title": "Updated Title",
 *     "author": "Updated Author",
 *     "genre": "Updated Genre",
 *     "publishedYear": 2020,
 *     "rating": 4.5
 *   }
 *
 * All fields are required for a full replacement (use PATCH for partial updates).
 *
 * Example curl command:
 *   curl -X PUT http://localhost:3000/api/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"To Kill a Mockingbird (Updated)","author":"Harper Lee","genre":"Fiction","publishedYear":1960,"rating":4.9}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return res.status(400).json({ success: false, error: 'Invalid book ID.' });
  }

  const { title, author, genre, publishedYear, rating } = req.body;

  // Validate required fields
  if (!title || !author || !genre || !publishedYear) {
    return res.status(400).json({
      success: false,
      error: 'Missing required fields: title, author, genre, and publishedYear are required.'
    });
  }

  // Attempt the update
  const updatedBook = updateBook(id, { title, author, genre, publishedYear, rating });

  if (!updatedBook) {
    return res.status(404).json({ success: false, error: `Book with ID ${id} not found.` });
  }

  res.json({ success: true, data: updatedBook });
});

// ──────────────────────────────────────────────
// DELETE /api/books/:id — Delete a book
// ──────────────────────────────────────────────

/**
 * @route   DELETE /api/books/:id
 * @desc    Remove a book from the collection by ID
 * @access  Public
 *
 * Path Parameters:
 *   - id (number) — The unique identifier of the book to delete
 *
 * Example curl command:
 *   # Delete book with ID 2
 *   curl -X DELETE http://localhost:3000/api/books/2
 *
 *   # Try deleting a non-existent book (returns 404)
 *   curl -X DELETE http://localhost:3000/api/books/999
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return res.status(400).json({ success: false, error: 'Invalid book ID.' });
  }

  const deleted = deleteBook(id);

  if (!deleted) {
    return res.status(404).json({ success: false, error: `Book with ID ${id} not found.` });
  }

  /**
   * Return 204 No Content on successful deletion.
   * 204 is standard when there's no response body to send back.
   */
  res.status(204).send();
});

// ──────────────────────────────────────────────
// Export the Router
// ──────────────────────────────────────────────

module.exports = router;
```

> **Why use `express.Router()`?** Routers let us organize routes into separate files while keeping them mounted under a single path prefix. This is how large Express apps scale — each feature gets its own router file.

