## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODEL — Camada de Dados da API de Livros
 * ============================================================
 *
 * POR QUE UM ARRAY EM MEMÓRIA?
 * ----------------------------
 * Para este exemplo educacional, utilizamos um array em memória
 * ao invés de um banco de dados real (MongoDB, PostgreSQL, etc.)
 * porque:
 *   1. Elimina a complexidade de configuração de infraestrutura
 *   2. Permite focar nos conceitos de REST, rotas e middleware
 *   3. Facilita o entendimento do fluxo completo de dados
 *
 * Em produção, substituiríamos este módulo por um serviço que
 * se comunica com um banco de dados real (ex: mongoose para MongoDB).
 *
 * ESTRUTURA DE DADOS ESCOLHIDA: Array de Objetos
 * -----------------------------------------------
 * Cada livro é representado como um objeto com as seguintes propriedades:
 *   - id        : número inteiro único (gerado automaticamente)
 *   - title     : string — título do livro
 *   - author    : string — nome do autor
 *   - year      : number — ano de publicação
 *   - genre     : string — gênero literário
 *   - isbn      : string — ISBN (identificador internacional)
 *   - createdAt : string ISO 8601 — data/hora de criação
 *   - updatedAt : string ISO 8601 — data/hora da última atualização
 *
 * Usamos um array porque:
 *   - A ordem de inserção é preservada (comportamento natural do Array)
 *   - Operações como filter(), find(), map() são nativas e legíveis
 *   - Para datasets pequenos (exemplo educacional), a performance é suficiente
 *
 * POR QUE NÃO USAR UM MAP/Objeto?
 * --------------------------------
 * Um Map ou objeto com IDs como chaves seria mais eficiente para buscas O(1).
 * No entanto, arrays são mais familiares e facilitam o aprendizado dos conceitos
 * de manipulação de dados em JavaScript. Em produção, um banco de dados resolve
 * isso automaticamente.
 */

// ============================================================
// ESTADO DA APLICAÇÃO (em memória)
// ============================================================
//
// O array `books` serve como nosso "banco de dados" temporário.
// Ele é inicializado com alguns livros de exemplo para facilitar os testes.
//
// IMPORTANTE: Em um servidor real, esse estado seria perdido ao reiniciar
// o processo. Bancos de dados persistem dados em disco; arrays em memória não.

/** @type {Array<Object>} Lista de livros armazenados em memória */
const books = [
  {
    id: 1,
    title: "Dom Casmurro",
    author: "Machado de Assis",
    year: 1899,
    genre: "Romance",
    isbn: "978-85-10-00001-5",
    createdAt: "2024-01-15T10:30:00.000Z",
    updatedAt: "2024-01-15T10:30:00.000Z"
  },
  {
    id: 2,
    title: "Dom Quixote",
    author: "Miguel de Cervantes",
    year: 1605,
    genre: "Romance",
    isbn: "978-85-10-00002-2",
    createdAt: "2024-01-15T10:31:00.000Z",
    updatedAt: "2024-01-15T10:31:00.000Z"
  },
  {
    id: 3,
    title: "O Senhor dos Anéis",
    author: "J.R.R. Tolkien",
    year: 1954,
    genre: "Fantasia",
    isbn: "978-85-10-00003-9",
    createdAt: "2024-01-15T10:32:00.000Z",
    updatedAt: "2024-01-15T10:32:00.000Z"
  }
];

/** @type {number} Contador para gerar IDs únicos sequenciais */
let nextId = 4; // Começa em 4 porque já temos 3 livros com IDs 1, 2 e 3

// ============================================================
// CLASSE DE ERRO PERSONALIZADA
// ============================================================
//
// Criamos uma classe Error personalizada para distinguir entre:
 *   - Erros de validação (400 Bad Request)
 *   - Erros de recurso não encontrado (404 Not Found)
 *   - Erros internos do servidor (500 Internal Server Error)
 *
 * Isso permite que o middleware de tratamento de erros responda com
 * códigos HTTP apropriados e mensagens claras para o cliente.

/**
 * Classe BookError — Extensão da classe nativa Error do JavaScript.
 *
 * POR QUE EXTENDER Error?
 * -----------------------
 * Ao estender a classe Error, mantemos a pilha de chamadas (stack trace)
 * intacta, o que é essencial para depuração. Adicionamos uma propriedade
 * `statusCode` personalizada para indicar o código HTTP correspondente.
 *
 * @example
 * throw new BookError("Livro não encontrado", 404);
 */
class BookError extends Error {
  /**
   * Cria uma instância de BookError.
   *
   * @param {string} message — Mensagem descritiva do erro
   * @param {number} statusCode — Código HTTP da resposta (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor da classe pai (Error)
    this.statusCode = statusCode; // Propriedade personalizada para o código HTTP
    this.name = "BookError"; // Nome da classe para fácil identificação

    // Mantém a pilha de chamadas correta em classes estendidas do Error
    // Sem esta linha, o stack trace seria truncado em alguns ambientes
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ============================================================
// FUNÇÕES DO MODEL — Operações CRUD sobre livros
// ============================================================

/**
 * Retorna todos os livros armazenados.
 *
 * @description
 * Esta função retorna uma cópia do array de livros para evitar que
 * o chamador modifique diretamente o estado interno (imutabilidade).
 * Em um cenário real com banco de dados, aqui faríamos a consulta SQL/NoSQL.
 *
 * @returns {Array<Object>} Array contendo todos os livros
 */
function getAllBooks() {
  return [...books]; // Spread operator cria uma cópia rasa do array
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @description
 * Utilizamos `Array.prototype.find()` que retorna o PRIMEIRO elemento
 * que satisfaz a condição de busca, ou `undefined` se nenhum for encontrado.
 *
 * POR QUE `find()` E NÃO `filter()[0]`?
 * --------------------------------------
 * - `find()` é mais eficiente: para em encontrar o primeiro match (O(n) no pior caso)
 * - `filter()[0]` percorre TODO o array mesmo após encontrar o elemento
 * - Para datasets pequenos a diferença é imperceptível, mas é uma boa prática
 *
 * @param {number} id — ID numérico do livro a ser buscado
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @description
 * A função gera automaticamente:
 *   - Um ID único usando o contador `nextId` (incrementado após uso)
 *   - Timestamps de criação e atualização usando `new Date().toISOString()`
 *
 * POR QUE USAR ISO 8601 PARA DATES?
 * ----------------------------------
 * O formato ISO 8601 ("2024-01-15T10:30:00.000Z") é:
 *   - Um padrão internacional reconhecido universalmente
 *   - Ordenável lexicalmente (strings podem ser comparadas diretamente)
 *   - Compatível com JavaScript nativo via `new Date(string)`
 *   - Mais legível que timestamps Unix para humanos
 *
 * @param {Object} bookData — Dados do novo livro
 * @param {string} bookData.title — Título do livro (obrigatório)
 * @param {string} bookData.author — Autor do livro (obrigatório)
 * @param {number} bookData.year — Ano de publicação (opcional, padrão: null)
 * @param {string} bookData.genre — Gênero literário (opcional, padrão: "Não informado")
 * @param {string} bookData.isbn — ISBN (opcional, padrão: null)
 * @returns {Object} O livro criado com todos os campos preenchidos
 * @throws {BookError} Se o título ou autor estiverem ausentes
 */
function createBook(bookData) {
  // Validação básica dos campos obrigatórios
  if (!bookData.title || bookData.title.trim() === "") {
    throw new BookError("O campo 'title' é obrigatório", 400);
  }
  if (!bookData.author || bookData.author.trim() === "") {
    throw new BookError("O campo 'author' é obrigatório", 400);
  }

  const now = new Date().toISOString();

  const newBook = {
    id: nextId++, // Atribui o ID atual e incrementa para a próxima vez
    title: bookData.title.trim(), // Remove espaços em branco extras
    author: bookData.author.trim(),
    year: bookData.year || null,
    genre: bookData.genre || "Não informado",
    isbn: bookData.isbn || null,
    createdAt: now,
    updatedAt: now
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo seu ID.
 *
 * @description
 * Utilizamos `Array.prototype.findIndex()` para localizar o índice do livro,
 * e em seguida atualizamos apenas os campos fornecidos (partial update).
 *
 * POR QUE PARCIAL UPDATE E NÃO SUBSTITUIÇÃO COMPLETA?
 * ---------------------------------------------------
 * REST permite dois comportamentos:
 *   - PUT completo: substitui TODOS os campos
 *   - PATCH parcial: atualiza APENAS os campos enviados
 *
 * Para este exemplo, tratamos PUT como atualização parcial dos campos
 * fornecidos no corpo da requisição, mantendo os demais inalterados.
 * Isso é mais amigável para o usuário, que não precisa reenviar todos
 * os campos a cada modificação.
 *
 * @param {number} id — ID do livro a ser atualizado
 * @param {Object} updates — Campos a serem atualizados
 * @returns {Object|null} O livro atualizado ou null se não encontrado
 * @throws {BookError} Se o livro não for encontrado (404)
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    // findIndex retorna -1 quando nenhum elemento satisfaz a condição
    throw new BookError(`Livro com ID ${id} não encontrado`, 404);
  }

  // Atualiza apenas os campos fornecidos, preservando os demais
  const allowedFields = ["title", "author", "year", "genre", "isbn"];
  for (const field of allowedFields) {
    if (updates[field] !== undefined) {
      books[index][field] = updates[field].trim && typeof updates[field] === "string"
        ? updates[field].trim()
        : updates[field];
    }
  }

  // Sempre atualiza o timestamp de modificação
  books[index].updatedAt = new Date().toISOString();

  return { ...books[index] }; // Retorna cópia para evitar mutação direta
}

/**
 * Exclui um livro do array pelo seu ID.
 *
 * @description
 * Utilizamos `Array.prototype.splice()` para remover o elemento no índice
 * encontrado. O splice modifica o array original e retorna um array com
 * os elementos removidos (usamos apenas para verificar se houve remoção).
 *
 * ALTERNATIVAS CONSIDERADAS:
 * --------------------------
 * - `filter()`: Cria um NOVO array sem o elemento removido. Mais funcional,
 *   mas aloca memória extra. Para arrays pequenos, a diferença é irrelevante.
 * - `splice()`: Modifica o array original in-place. Mais eficiente em memória.
 *
 * Escolhemos splice por ser mais direto e eficiente para este caso de uso.
 *
 * @param {number} id — ID do livro a ser excluído
 * @returns {boolean} true se o livro foi encontrado e removido, false caso contrário
 * @throws {BookError} Se o livro não for encontrado (404)
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    throw new BookError(`Livro com ID ${id} não encontrado`, 404);
  }

  books.splice(index, 1); // Remove 1 elemento na posição index
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * @description
 * Esta função percorre o array uma única vez (O(n)) e calcula:
 *   - total: quantidade total de livros
 *   - porGenero: contagem de livros agrupados por gênero
 *   - mediaAnos: média dos anos de publicação (null se não houver livros)
 *   - autorMaisProdutivo: autor com mais livros no acervo
 *
 * POR QUE CALCULAR TUDO EM UMA ÚNICA PASSAGEM?
 * ---------------------------------------------
 * Embora pudéssemos chamar funções separadas para cada estatística,
 * fazer tudo em um único loop é mais eficiente (O(n) vs O(4n)).
 * Para datasets pequenos a diferença é mínima, mas é uma boa prática
 * de programação pensar em eficiência desde o início.
 *
 * @returns {Object} Estatísticas do acervo
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando objeto como mapa
  const porGenero = {};
  let autorMaisProdutivo = null;
  const contagemAutores = {};

  for (const book of books) {
    // Contagem por gênero
    const genero = book.genre || "Não informado";
    porGenero[genero] = (porGenero[genero] || 0) + 1;

    // Contagem por autor
    if (book.author) {
      contagemAutores[book.author] = (contagemAutores[book.author] || 0) + 1;
    }

    // Acumula anos para cálculo da média
    if (book.year !== null && book.year !== undefined) {
      // A média será calculada após o loop
    }
  }

  // Encontra o autor mais produtivo
  let maxCount = 0;
  for (const [autor, count] of Object.entries(contagemAutores)) {
    if (count > maxCount) {
      maxCount = count;
      autorMaisProdutivo = { autor, quantidade: count };
    }
  }

  // Calcula a média dos anos de publicação
  const livrosComAno = books.filter(b => b.year !== null && b.year !== undefined);
  const mediaAnos = livrosComAno.length > 0
    ? livrosComAno.reduce((sum, b) => sum + b.year, 0) / livrosComAno.length
    : null;

  return {
    total,
    porGenero,
    mediaAnos: mediaAnos ? Math.round(mediaAnos * 100) / 100 : null, // Arredonda para 2 casas decimais
    autorMaisProdutivo
  };
}

// ============================================================
// EXPORTAÇÃO DOS MÓDULOS
// ============================================================
//
// Usamos exports nominais (named exports) ao invés de module.exports = {}
 * porque:
 *   - Permite importar apenas o que é necessário: import { getAllBooks } from './book.js'
 *   - Facilita a refatoração (renomear funções sem quebrar imports)
 *   - É o padrão recomendado pela especificação ES Modules

module.exports = {
  BookError,
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

