## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE — Tratamento Centralizado de Erros
 * ============================================================
 *
 * O QUE É MIDDLEWARE NO EXPRESS?
 * -------------------------------
 * Middleware são funções que têm acesso ao objeto de requisição (req),
 * resposta (res) e à função `next` do ciclo de requisição. Elas podem:
 *   1. Executar código arbitrário
 *   2. Modificar os objetos req e res
 *   3. Encerrar o ciclo de requisição-resposta
 *   4. Chamar o próximo middleware com `next()`
 *
 * POR QUE UM MIDDLEWARE DE ERROS SEPARADO?
 * -----------------------------------------
 * O Express trata middlewares de erro de forma especial: eles recebem
 * QUATRO argumentos (err, req, res, next) ao invés de três. Ao centralizar
 * o tratamento de erros em um único middleware, garantimos que:
 *   - Todas as respostas de erro tenham o mesmo formato JSON
 *   - Nenhum erro não tratado chegue ao cliente como "500 genérico"
 *   - A lógica de formatação de resposta seja consistente em toda a API
 *
 * O middleware deve ser o ÚLTIMO middleware registrado no app, pois ele
 * só é executado quando um erro é passado para `next(err)`.
 */

/**
 * Middleware de tratamento de erros.
 *
 * @description
 * Este middleware captura todos os erros lançados nas rotas e responde
 * com um JSON padronizado contendo:
 *   - statusCode: código HTTP da resposta
 *   - error: nome/tipo do erro
 *   - message: mensagem descritiva para o cliente
 *   - timestamp: data/hora da ocorrência (formato ISO 8601)
 *
 * Se o erro não for uma instância de BookError, assumimos um erro interno
 * do servidor (500) com uma mensagem genérica para não expor detalhes
 * internos da aplicação ao cliente.
 *
 * @param {Error} err — O objeto de erro lançado
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 * @param {Function} next — Função para encadear ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // Logging do erro no servidor (para depuração)
  // Em produção, use um sistema de logging adequado (Winston, Pino, etc.)
  console.error(`[ERROR] ${new Date().toISOString()} —`, err.message);

  // Determina o código HTTP e a mensagem com base no tipo de erro
  const statusCode = err.statusCode || 500;
  const message = err.name === "BookError"
    ? err.message
    : "Erro interno do servidor. Por favor, tente novamente mais tarde.";

  // Envia a resposta JSON padronizada
  res.status(statusCode).json({
    success: false,
    error: err.name || "Error",
    message,
    timestamp: new Date().toISOString()
  });
}

/**
 * Middleware para lidar com rotas não encontradas (404).
 *
 * @description
 * Este middleware é executado quando nenhuma rota corresponde à URL
 * solicitada. Ele lança um BookError com código 404, que será capturado
 * pelo middleware errorHandler acima.
 *
 * POR QUE LANÇAR UM ERRO E NÃO RESPONDER DIRETAMENTE?
 * ---------------------------------------------------
 * Ao lançar um erro e deixá-lo ser capturado pelo errorHandler, mantemos
 * a consistência no formato de resposta. Se respondêssemos diretamente
 * aqui, teríamos dois formatos diferentes para erros 404 (um nas rotas
 * e outro nas rotas não encontradas).
 *
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 * @param {Function} next — Função para encadear ao próximo middleware
 */
function notFoundHandler(req, res, next) {
  // Lança um erro que será capturado pelo errorHandler
  const { BookError } = require("../models/book");
  next(new BookError(`Rota ${req.method} ${req.path} não encontrada`, 404));
}

module.exports = { errorHandler, notFoundHandler };
```

