## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS — Definição dos Endpoints da API de Livros
 * ============================================================
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar as rotas em um arquivo distinto permite:
 *   1. Manter o app.js limpo e focado na configuração do servidor
 *   2. Facilitar a adição de novas rotas sem modificar o arquivo principal
 *   3. Permitir que diferentes desenvolvedores trabalhem em rotas diferentes
 *      simultaneamente (menos conflitos de merge no versionamento)
 *
 * O Express fornece dois tipos de objetos Router:
 *   - app.use() — Middleware aplicado globalmente
 *   - router.get/post/put/delete() — Rotas específicas com path e handler
 *
 * Usamos `express.Router()` para criar um roteador modular que é
 * então "conectado" ao app principal em app.js.
 */

const express = require("express");

// Importa as funções do model (camada de dados)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  BookError
} = require("../models/book");

// Cria um roteador Express — é como um "mini-app" que contém apenas rotas
const router = express.Router();

// ============================================================
// VALIDAÇÃO DE ID NUMÉRICO (Middleware de Rota)
// ============================================================
//
 * Este middleware é aplicado a todas as rotas que recebem :id nos parâmetros.
 * Ele verifica se o ID fornecido é um número válido antes de executar o handler.
 *
 * POR QUE VALIDAR NO NÍVEL DA ROTA?
 * ----------------------------------
 * A validação deve ocorrer o mais cedo possível no ciclo de requisição.
 * Se o ID for inválido, não faz sentido consultar o banco de dados ou
 * executar a lógica de negócio — basta rejeitar a requisição imediatamente.
 *
 * O Express permite encadear middlewares antes do handler final:
 *   router.get("/:id", validateId, getBookHandler)
 *
 * Se `validateId` chamar next(err), o fluxo é interrompido e o erro
 * é capturado pelo middleware errorHandler global.

/**
 * Middleware para validar se o parâmetro de ID é um número inteiro positivo.
 *
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express (não usado aqui)
 * @param {Function} next — Função para encadear ao próximo middleware ou handler
 */
function validateId(req, res, next) {
  const id = parseInt(req.params.id, 10); // Converte string do parâmetro para número

  if (isNaN(id) || id <= 0) {
    // Se o ID não for um número válido, lança um erro que será capturado pelo errorHandler
    return next(new BookError("ID inválido. Deve ser um número inteiro positivo.", 400));
  }

  // Passa o ID como número para o handler (em vez da string original)
  req.params.id = id;
  next(); // Continua para o próximo middleware ou handler
}

// ============================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================
//
 * MÉTODO HTTP: GET
 * URL: /books
 * Parâmetros de query (opcionais):
 *   - genre    : filtra por gênero literário
 *   - author   : filtra por autor (busca parcial, case-insensitive)
 *   - minYear  : filtra livros publicados a partir deste ano
 *   - maxYear  : filtra livros publicados até este ano
 *   - page     : número da página (paginação, padrão: 1)
 *   - limit    : quantidade de itens por página (padrão: 10, máximo: 100)
 *
 * POR QUE FILTRAGEM VIA QUERY PARAMETERS?
 * ----------------------------------------
 * Em REST, parâmetros de filtragem e paginação são passados como query strings
 * porque não fazem parte do recurso em si — são metadados sobre COMO buscar
 * o recurso. Exemplo: /books?genre=Fantasia&page=2&limit=5
 *
 * O código a seguir demonstra o uso de Array.prototype.filter() para
 * aplicar múltiplos filtros de forma encadeada e legível.

/**
 * Handler para GET /books — Lista todos os livros com suporte a filtragem.
 *
 * @async
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 */
router.get("/books", (req, res) => {
  try {
    // Obtém os parâmetros de query com valores padrão
    const { genre, author, minYear, maxYear, page = 1, limit = 10 } = req.query;

    // Começa com todos os livros e aplica filtros sequencialmente
    let result = getAllBooks();

    // Filtro por gênero (case-insensitive)
    if (genre) {
      result = result.filter(book =>
        book.genre.toLowerCase() === genre.toLowerCase()
      );
    }

    // Filtro por autor (busca parcial, case-insensitive)
    // Ex: author="tolkien" encontra "J.R.R. Tolkien"
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter(book =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // Filtro por ano mínimo de publicação
    if (minYear) {
      const min = parseInt(minYear, 10);
      result = result.filter(book => book.year >= min);
    }

    // Filtro por ano máximo de publicação
    if (maxYear) {
      const max = parseInt(maxYear, 10);
      result = result.filter(book => book.year <= max);
    }

    // Paginação: calcula o índice inicial e final
    const pageNum = Math.max(1, parseInt(page, 10));
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10)));
    const total = result.length;
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = startIndex + limitNum;

    // slice() retorna uma cópia do array entre os índices (não modifica o original)
    const paginatedBooks = result.slice(startIndex, endIndex);

    // Resposta com metadados de paginação
    res.json({
      success: true,
      data: paginatedBooks,
      pagination: {
        currentPage: pageNum,
        totalPages: Math.ceil(total / limitNum),
        totalItems: total,
        itemsPerPage: limitNum
      }
    });
  } catch (error) {
    // Passa o erro para o middleware errorHandler
    next(error);
  }
});

// ============================================================
// GET /books/stats — Retornar estatísticas do acervo
// ============================================================
//
 * MÉTODO HTTP: GET
 * URL: /books/stats
 * Resposta: objeto com total, contagem por gênero, média de anos e autor mais produtivo
 *
 * Esta rota demonstra um endpoint que não opera sobre um recurso específico,
 * mas sim sobre o conjunto de recursos — algo comum em APIs REST para
 * métricas e dashboards.

/**
 * Handler para GET /books/stats — Retorna estatísticas do acervo.
 *
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 */
router.get("/books/stats", (req, res) => {
  try {
    const stats = getStats();

    res.json({
      success: true,
      data: stats
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// GET /books/:id — Obter um livro específico pelo ID
// ============================================================
//
 * MÉTODO HTTP: GET
 * URL: /books/:id
 * Parâmetro de rota: id (número inteiro)
 * Resposta: objeto com o livro completo ou erro 404 se não encontrado
 *
 * O uso de `validateId` como middleware garante que o ID seja válido
 * antes de qualquer consulta ao modelo.

/**
 * Handler para GET /books/:id — Busca um livro pelo ID.
 *
 * @param {Object} req — Objeto de requisição do Express (req.params.id já validado)
 * @param {Object} res — Objeto de resposta do Express
 */
router.get("/books/:id", validateId, (req, res) => {
  try {
    const book = getBookById(req.params.id);

    if (!book) {
      // Lança erro 404 que será capturado pelo middleware errorHandler
      throw new BookError(`Livro com ID ${req.params.id} não encontrado`, 404);
    }

    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
//
 * MÉTODO HTTP: POST
 * URL: /books
 * Body (JSON): { title, author, year?, genre?, isbn? }
 * Resposta: o livro criado com status 201 (Created)
 *
 * POR QUE STATUS 201 E NÃO 200?
 * ------------------------------
 * O código 201 Created é semanticamente correto para operações de criação,
 * indicando que um novo recurso foi criado no servidor. O 200 OK seria
 * ambíguo (poderia significar "a operação foi bem-sucedida" sem especificar
 * o resultado). REST recomenda usar códigos específicos para cada ação.
 *
 * O header Location é incluído para indicar a URL do recurso criado,
 * seguindo a convenção HATEOAS (Hypermedia as the Engine of Application State).

/**
 * Handler para POST /books — Cria um novo livro.
 *
 * @param {Object} req — Objeto de requisição do Express (req.body contém os dados)
 * @param {Object} res — Objeto de resposta do Express
 */
router.post("/books", (req, res) => {
  try {
    // O middleware body-parser (aplicado em app.js) já parseou o JSON para req.body
    const newBook = createBook(req.body);

    // 201 Created + header Location apontando para o novo recurso
    res.status(201).json({
      success: true,
      data: newBook,
      location: `/books/${newBook.id}`
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================
//
 * MÉTODO HTTP: PUT
 * URL: /books/:id
 * Body (JSON): campos a serem atualizados
 * Resposta: o livro atualizado com status 200 (OK)
 *
 * POR QUE PUT E NÃO PATCH?
 * -------------------------
 * Tecnicamente, PUT deveria substituir O RECURSO INTEIRO, enquanto PATCH
 * atualiza parcialmente. No entanto, na prática muitas APIs tratam PUT
 * como atualização parcial para melhor experiência do desenvolvedor.
 *
 * Para este exemplo, implementamos PUT como atualização parcial dos
 * campos fornecidos, mantendo os demais inalterados. Em uma API real,
 * você poderia implementar ambos: PUT (substituição completa) e PATCH
 * (atualização parcial).

/**
 * Handler para PUT /books/:id — Atualiza um livro existente.
 *
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 */
router.put("/books/:id", validateId, (req, res) => {
  try {
    const updatedBook = updateBook(req.params.id, req.body);

    res.json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// DELETE /books/:id — Excluir um livro
// ============================================================
//
 * MÉTODO HTTP: DELETE
 * URL: /books/:id
 * Resposta: status 204 No Content (sem corpo na resposta)
 *
 * POR QUE 204 NO CONTENT?
 * ------------------------
 * O código 204 indica que a operação foi bem-sucedida mas não há conteúdo
 * para retornar no corpo da resposta. Isso é mais eficiente (menos bytes
 * transmitidos) e semanticamente correto, pois o recurso foi removido.
 *
 * Alguns desenvolvedores preferem retornar 200 com uma mensagem de confirmação.
 * Ambas as abordagens são válidas; 204 segue mais rigorosamente a especificação REST.

/**
 * Handler para DELETE /books/:id — Exclui um livro pelo ID.
 *
 * @param {Object} req — Objeto de requisição do Express
 * @param {Object} res — Objeto de resposta do Express
 */
router.delete("/books/:id", validateId, (req, res) => {
  try {
    deleteBook(req.params.id);

    // 204 No Content — operação bem-sucedida sem corpo na resposta
    res.status(204).end();
  } catch (error) {
    next(error);
  }
});

// ============================================================
// EXPORTAÇÃO DO ROTEADOR
// ============================================================
module.exports = router;
```

