## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * APP — Ponto de Entrada da API REST de Livros
 * ============================================================
 *
 * ESTRUTURA DE INICIALIZAÇÃO DO EXPRESS:
 * ---------------------------------------
 * 1. Criar a instância do app Express
 * 2. Configurar middlewares globais (body-parser, JSON parsing)
 * 3. Registrar as rotas
 * 4. Registrar o middleware de tratamento de erros (SEMPRE por último)
 * 5. Iniciar o servidor em uma porta
 *
 * POR QUE USAR `express.json()`?
 * ------------------------------
 * O Express não faz parsing automático do corpo das requisições.
 * O middleware `express.json()` converte o body de formato JSON
 * (string) para um objeto JavaScript, tornando-o acessível via `req.body`.
 *
 * Sem este middleware, `req.body` seria undefined e não conseguiríamos
 * ler os dados enviados pelo cliente no POST/PUT.
 */

const express = require("express");

// Importa as rotas definidas em routes/books.js
const bookRoutes = require("./routes/books");

// Importa o middleware de tratamento de erros
const { errorHandler, notFoundHandler } = require("./middleware/errorHandler");

// Cria a instância principal do aplicativo Express
const app = express();

// ============================================================
// CONFIGURAÇÃO DE MIDDLEWARES GLOBAIS
// ============================================================

/**
 * Middleware para parsing de JSON no corpo das requisições.
 *
 * Configura o limite máximo de payload para 100KB (padrão do Express é 100KB).
 * Aumentar este valor pode ser necessário se os livros tiverem descrições longas.
 */
app.use(express.json({ limit: "100kb" }));

/**
 * Middleware para logging básico de requisições.
 *
 * Exibe no console do servidor: método HTTP, URL e timestamp de cada requisição.
 * Em produção, substitua por um logger adequado (Winston, Pino, etc.).
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next(); // Passa o controle para o próximo middleware
});

// ============================================================
// REGISTRO DAS ROTAS
// ============================================================
//
 * `app.use('/books', bookRoutes)` conecta todas as rotas definidas
 * no roteador de livros ao caminho base `/books`.
 *
 * Isso significa que:
 *   - router.get("/books")       → app.get("/books")
 *   - router.get("/books/:id")   → app.get("/books/:id")
 *   - router.post("/books")      → app.post("/books")
 *   - etc.
 *
 * Se tivéssemos múltiplos conjuntos de rotas (ex: /users, /authors),
 * registraríamos cada um separadamente:
 *   app.use('/users', userRoutes);
 *   app.use('/authors', authorRoutes);

app.use("/books", bookRoutes);

// ============================================================
// ROTA RAIZ — Informação sobre a API
// ============================================================
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "API de Livros REST — Exemplo Educacional",
    endpoints: {
      list: "GET /books",
      stats: "GET /books/stats",
      getById: "GET /books/:id",
      create: "POST /books",
      update: "PUT /books/:id",
      delete: "DELETE /books/:id"
    }
  });
});

// ============================================================
// MIDDLEWARES DE TRATAMENTO DE ERROS
// ============================================================
//
 * IMPORTANTE: Estes middlewares DEVEM ser registrados POR ÚLTIMO,
 * após todas as rotas. O Express executa middlewares na ordem em que
 * foram registrados, e os middlewares de erro só são chamados quando
 * um erro é passado para `next(err)`.
 *
 * A ordem é crítica:
 *   1. Middlewares globais (body-parser, logging)
 *   2. Rotas (bookRoutes)
 *   3. Middleware 404 (rotas não encontradas)
 *   4. Middleware de tratamento de erros (captura todos os erros)

// Captura requisições para rotas que não existem
app.use(notFoundHandler);

// Captura e trata todos os erros lançados nas rotas
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor HTTP na porta configurada.
 *
 * A função arrow async é usada para permitir expansão futura com
 * operações assíncronas de inicialização (ex: conectar a um banco de dados).
 */
app.listen(PORT, () => {
  console.log(`\n========================================`);
  console.log(`  API de Livros REST rodando na porta ${PORT}`);
  console.log(`  http://localhost:${PORT}/`);
  console.log(`========================================\n`);
});

module.exports = app;
```

