## File 2: `src/models/bookStore.js` — In-Memory Data Store

```javascript
/**
 * ============================================================================
 * BOOK DATA STORE (In-Memory)
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * We use an in-memory array instead of a database for this educational example.
 * This keeps the project self-contained with zero external dependencies beyond
 * Express. In production, you would replace this module with a MongoDB/PostgreSQL
 * service — the route handlers above would remain unchanged thanks to our clean
 * separation of concerns.
 *
 * DATA STRUCTURE CHOICE:
 * - Array of objects: Simple and intuitive for CRUD operations.
 * - Each book has a unique numeric `id` (auto-incrementing) rather than UUIDs,
 *   because numeric IDs are easier to read in examples and demonstrate the
 *   concept clearly. In production, UUIDs or MongoDB ObjectIds are preferred
 *   to avoid collision risks in distributed systems.
 * - The `createdAt` / `updatedAt` timestamps use ISO 8601 strings (Date.toISOString())
 *   because they are timezone-agnostic and sortable lexicographically.
 *
 * CONCURRENCY NOTE:
 * In-memory arrays are NOT thread-safe. For a production app, you'd need locks
 * or an actual database. This is acceptable for a single-process educational demo.
 */

// --------------------------------------------------------------------------
// Module-level state
// --------------------------------------------------------------------------

/**
 * @type {Array<Object>} books
 * The in-memory collection of all book records.
 * Each object has the shape:
 *   { id: number, title: string, author: string, genre: string, year: number }
 */
const books = [];

/**
 * @type {number} nextId
 * Tracks the next ID to assign when creating a new book.
 * Initialized at 1 so IDs start at 1 (not 0), which is more intuitive.
 */
let nextId = 1;

// --------------------------------------------------------------------------
// Seed data — provides realistic sample books for testing
// --------------------------------------------------------------------------

/**
 * Seeds the store with 5 sample books if it's currently empty.
 * This runs automatically when the module loads so the API isn't blank on start.
 */
function seedData() {
  // Only seed once — prevents duplicate data on hot-reload during development
  if (books.length > 0) return;

  const sampleBooks = [
    {
      id: nextId++,
      title: 'To Kill a Mockingbird',
      author: 'Harper Lee',
      genre: 'Fiction',
      year: 1960,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    },
    {
      id: nextId++,
      title: '1984',
      author: 'George Orwell',
      genre: 'Dystopian',
      year: 1949,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    },
    {
      id: nextId++,
      title: 'The Great Gatsby',
      author: 'F. Scott Fitzgerald',
      genre: 'Fiction',
      year: 1925,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    },
    {
      id: nextId++,
      title: 'Dune',
      author: 'Frank Herbert',
      genre: 'Science Fiction',
      year: 1965,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    },
    {
      id: nextId++,
      title: 'The Hobbit',
      author: 'J.R.R. Tolkien',
      genre: 'Fantasy',
      year: 1937,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    }
  ];

  // Push each sample book into our in-memory array
  books.push(...sampleBooks);
}

// --------------------------------------------------------------------------
// Public API — these functions are the ONLY way to interact with the store
// This encapsulation makes it easy to swap out for a database later.
// --------------------------------------------------------------------------

/**
 * Retrieves all books from the store.
 * @returns {Array<Object>} A shallow copy of the books array (prevents external mutation).
 */
function getAllBooks() {
  return [...books]; // Return a copy, not the original reference
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|undefined} The book object if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Creates a new book and adds it to the store.
 * Auto-assigns an incrementing ID and timestamps.
 * @param {Object} bookData - The book data (title, author, genre, year).
 * @returns {Object} The newly created book with assigned id, createdAt, updatedAt.
 */
function createBook(bookData) {
  const now = new Date().toISOString();

  const newBook = {
    id: nextId++,
    ...bookData, // Spread in the provided fields (title, author, genre, year)
    createdAt: now,
    updatedAt: now
  };

  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with partial or full data.
 * Only updates fields that are explicitly provided in the update object.
 * @param {number} id - The ID of the book to update.
 * @param {Object} updateData - Fields to update (any subset of title, author, genre, year).
 * @returns {Object|undefined} The updated book if found, otherwise undefined.
 */
function updateBook(id, updateData) {
  const index = books.findIndex(book => book.id === id);

  // Return undefined if the book doesn't exist (caller handles the error)
  if (index === -1) return undefined;

  // Merge: keep existing fields, override with provided ones
  books[index] = {
    ...books[index],
    ...updateData,
    updatedAt: new Date().toISOString() // Always refresh the timestamp
  };

  return books[index];
}

/**
 * Deletes a book by its ID.
 * @param {number} id - The unique identifier of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) return false;

  books.splice(index, 1); // Remove exactly one element at the given index
  return true;
}

/**
 * Computes aggregate statistics about the book collection.
 * @returns {Object} Statistics including total count, genre breakdown, author count, and year range.
 */
function getStats() {
  const totalBooks = books.length;

  // Group books by genre to count occurrences per genre
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }

  // Count distinct authors
  const uniqueAuthors = new Set(books.map(book => book.author)).size;

  // Find the earliest and latest publication years
  const years = books.map(book => book.year);
  const minYear = years.length ? Math.min(...years) : null;
  const maxYear = years.length ? Math.max(...years) : null;

  return {
    totalBooks,
    uniqueAuthors,
    genres: genreCounts,
    yearRange: { min: minYear, max: maxYear }
  };
}

// --------------------------------------------------------------------------
// Initialize — seed data on module load
// --------------------------------------------------------------------------
seedData();

// --------------------------------------------------------------------------
// Export all functions as a single object (CommonJS pattern)
// This is the standard Node.js module export style.
// --------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
