```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * We define custom error classes that extend the built-in Error class. This gives
 * us typed errors we can catch and respond to with appropriate HTTP status codes.
 * For example, a NotFoundError always maps to 404, while a ValidationError maps
 * to 400. This is cleaner than checking error messages as strings.
 *
 * The expressAsyncHandler wrapper (manual implementation below) catches errors
 * thrown inside async route handlers and forwards them to our error middleware,
 * preventing unhandled promise rejections from crashing the server.
 *
 * Express error-handling middleware has a special signature: (err, req, res, next).
 * If you add a 4th parameter, Express recognizes it as an error handler.
 */

// --------------------------------------------------------------------------
// Custom Error Classes
// --------------------------------------------------------------------------

/**
 * Base class for all application-specific errors.
 * Extends the native Error class and adds a numeric statusCode property.
 * This allows our middleware to read err.statusCode and send the right HTTP code.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (e.g., 400, 404, 500).
   */
  constructor(message, statusCode) {
    super(message); // Call the parent Error constructor with our message

    // Capture the name for stack traces — without this, all instances show "Error"
    this.name = this.constructor.name;

    // Attach the HTTP status code so middleware can use it
    this.statusCode = statusCode;

    // Keep the stack trace clean by setting the origin point
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Thrown when a requested resource (e.g., a book) is not found.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    // "Book not found" or "Author not found" etc.
    super(`${resource} not found`, 404);
  }
}

/**
 * Thrown when client input fails validation (missing fields, wrong types, etc.).
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

// --------------------------------------------------------------------------
// Async Handler Wrapper
// --------------------------------------------------------------------------

/**
 * Wraps an async Express route handler so that any thrown error is caught
 * and passed to next(err) instead of causing an unhandled rejection.
 *
 * WHY THIS EXISTS: In Express, if an async function throws, the error is NOT
 * automatically caught by the framework. Without this wrapper, a thrown error
 * inside an async route would crash the process with "UnhandledPromiseRejection".
 *
 * @param {Function} fn - The async route handler function.
 * @returns {Function} A new function compatible with Express's (req, res, next) signature.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Call the wrapped function and catch any rejection
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// --------------------------------------------------------------------------
// Validation Middleware — reusable field-checker for POST/PUT requests
// --------------------------------------------------------------------------

/**
 * Creates middleware that validates required fields in the request body.
 * This is a higher-order function: it returns a new middleware function.
 *
 * @param {Array<string>} requiredFields - Field names that must be present and non-empty.
 * @returns {Function} Express middleware that calls next(err) on validation failure.
 */
function validateBody(...requiredFields) {
  return (req, res, next) => {
    // Collect all missing or empty fields from the request body
    const missing = requiredFields.filter(field => {
      const value = req.body[field];
      // Check for undefined, null, empty string, or whitespace-only strings
      return value === undefined || value === null || String(value).trim() === '';
    });

    if (missing.length > 0) {
      // Return a clear error listing all missing fields
      return next(new ValidationError(
        `Missing required field(s): ${missing.join(', ')}`
      ));
    }

    // All validations passed — proceed to the next middleware/route handler
    next();
  };
}

/**
 * Validates that an ID parameter is a positive integer.
 * Used as middleware on routes like GET /books/:id.
 *
 * @param {string} paramKey - The request property holding the ID (e.g., 'params', 'query').
 * @param {string} paramName - The name of the parameter (e.g., 'id').
 * @returns {Function} Express middleware.
 */
function validateId(paramKey = 'params', paramName = 'id') {
  return (req, res, next) => {
    const idValue = req[paramKey][paramName];

    // Parse as integer and check it's a valid positive number
    const id = Number(idValue);
    if (!Number.isInteger(id) || id < 1) {
      return next(new ValidationError(`Invalid ${paramName}: must be a positive integer`));
    }

    // Attach the parsed ID to req for downstream use (avoids repeated parsing)
    req[paramName] = id;
    next();
  };
}

// --------------------------------------------------------------------------
// Global Error-Handling Middleware
// --------------------------------------------------------------------------

/**
 * Catches ALL errors in the Express pipeline and sends a consistent JSON response.
 *
 * EXPRESS PATTERN: This function has 4 parameters (err, req, res, next). Express
 * specifically looks for this signature to identify error-handling middleware.
 * Normal middleware has only 3 parameters (req, res, next).
 *
 * ORDER MATTERS: This must be registered AFTER all routes so it acts as a fallback.
 * If placed before routes, it would intercept normal responses incorrectly.
 *
 * @param {Error} err - The error object (our custom AppError or native Error).
 * @param {Object} req - The Express request object.
 * @param {Object} res - The Express response object.
 * @param {Function} next - The Express next function (unused here).
 */
function errorHandler(err, req, res, next) {
  // Determine the status code: use err.statusCode if available, default to 500
  const statusCode = err.statusCode || 500;

  // In production, you would NOT send the full error message or stack trace
  // to the client — it could leak sensitive information. For this educational
  // example, we include them so you can see what's happening.
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Build a consistent JSON error response shape
  const errorResponse = {
    success: false,
    statusCode,
    message: err.message,
    // Only include the stack trace in non-production environments
    ...(isDevelopment && { stack: err.stack })
  };

  // Log the full error (with stack) to the server console for debugging
  console.error(`[ERROR ${statusCode}] ${err.message}`);
  if (isDevelopment && err.stack) {
    console.error(err.stack);
  }

  // Send the JSON response
  res.status(statusCode).json(errorResponse);
}

// --------------------------------------------------------------------------
// 404 Fallback — catches requests to undefined routes
// --------------------------------------------------------------------------

/**
 * Middleware that handles requests to routes that don't exist.
 * Must be registered AFTER all route definitions.
 */
function notFoundHandler(req, res, next) {
  // This is NOT an error object, so we call next() with a NotFoundError
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
}

// --------------------------------------------------------------------------
// Module Exports
// --------------------------------------------------------------------------
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  asyncHandler,
  validateBody,
  validateId,
  errorHandler,
  notFoundHandler
};
