```javascript
/**
 * ============================================================================
 * BOOK ROUTES
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * We use Express Router to create a modular set of routes. This keeps the main
 * app.js file clean and makes it easy to add more route modules later (e.g.,
 * /authors, /reviews). The router is mounted at '/books' in app.js.
 *
 * HTTP METHOD CONVENTIONS:
 * - GET    /books          → List all books (with optional query filters)
 * - GET    /books/:id      → Get a single book by ID
 * - POST   /books          → Create a new book
 * - PUT    /books/:id      → Fully update an existing book
 * - DELETE /books/:id      → Delete a book by ID
 *
 * WHY PUT vs PATCH? We use PUT (full replacement) rather than PATCH (partial)
 * for simplicity in this educational example. In production, you'd typically
 * support both. Our store's updateBook function already handles partial updates
 * via object spreading, so either approach works.
 *
 * ASYNC/AWAIT PATTERN: All handlers are async functions wrapped with asyncHandler.
 * This is the modern Node.js pattern — it's more readable than .then() chains
 * and avoids the callback pyramid of doom. Even though our in-memory store is
 * synchronous, using async handlers prepares the code for when we switch to a
 * real database (which will be async).
 */

const express = require('express');

// Import our custom error utilities and validation middleware
const {
  asyncHandler,
  validateBody,
  validateId,
  NotFoundError
} = require('../middleware/errorHandler');

// Import the in-memory data store functions
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
} = require('../models/bookStore');

// Create an Express Router instance — this is a mini-app that only handles /books routes
const router = express.Router();

// ============================================================================
// GET /stats — Book Collection Statistics
// ============================================================================

/**
 * @route   GET /stats
 * @desc    Return aggregate statistics about the book collection
 * @access  Public (no authentication in this educational example)
 *
 * RESPONSE EXAMPLE:
 * {
 *   "success": true,
 *   "data": {
 *     "totalBooks": 5,
 *     "uniqueAuthors": 5,
 *     "genres": { "Fiction": 2, "Dystopian": 1, "Science Fiction": 1, "Fantasy": 1 },
 *     "yearRange": { "min": 1925, "max": 1965 }
 *   }
 * }
 */
router.get('/stats', asyncHandler(async (req, res) => {
  // Call the stats function from our data store
  const stats = getStats();

  // Send a consistent JSON response with success flag and data wrapper
  res.json({
    success: true,
    data: stats
  });
}));

// ============================================================================
// GET /books — List All Books (with optional filtering)
// ============================================================================

/**
 * @route   GET /books
 * @desc    Retrieve a list of all books with optional query parameter filters
 * @access  Public
 *
 * QUERY PARAMETERS (all optional):
 *   - author  : Filter by author name (case-insensitive partial match)
 *   - genre   : Filter by exact genre match
 *   - search  : Search title AND author (case-insensitive partial match)
 *   - sort    : Sort field — "title", "author", "year" (default: no sorting)
 *   - order   : "asc" or "desc" (default: "asc")
 *
 * RESPONSE EXAMPLE (with ?genre=Fiction):
 * {
 *   "success": true,
 *   "data": [
 *     { "id": 1, "title": "To Kill a Mockingbird", "author": "Harper Lee", ... },
 *     { "id": 3, "title": "The Great Gatsby",    "author": "F. Scott Fitzgerald", ... }
 *   ]
 * }
 */
router.get('/', asyncHandler(async (req, res) => {
  // Destructure query parameters from the URL (e.g., /books?genre=Fiction&sort=year)
  const { author, genre, search, sort, order } = req.query;

  // Start with a full copy of all books
  let result = getAllBooks();

  // Apply filters only if the corresponding query parameter is provided
  // This uses short-circuit evaluation: if 'genre' is undefined, this line does nothing

  /**
   * FILTERING LOGIC:
   * We chain .filter() calls because each one returns a new array that the next
   * filter operates on. This is more efficient than multiple passes over the data
   * and keeps the code readable. In a real database, these would become SQL WHERE clauses.
   */

  // Filter by author (case-insensitive partial match — e.g., "orwell" matches "George Orwell")
  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorLower));
  }

  // Filter by exact genre match (case-insensitive)
  if (genre) {
    const genreLower = genre.toLowerCase();
    result = result.filter(book => book.genre.toLowerCase() === genreLower);
  }

  // Search across both title and author fields
  if (search) {
    const searchLower = search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchLower) ||
      book.author.toLowerCase().includes(searchLower)
    );
  }

  // Apply sorting if a sort field is specified
  if (sort) {
    // Determine sort direction: default to ascending, allow "desc" override
    const sortOrder = order === 'desc' ? -1 : 1;

    /**
     * SORTING LOGIC:
     * Array.prototype.sort() mutates the array in place, so we use [...result] to
     * create a shallow copy first. We compare based on the sort field dynamically.
     * For strings, we use localeCompare for proper alphabetical ordering.
     */
    result = [...result].sort((a, b) => {
      if (typeof a[sort] === 'string') {
        return sortOrder * a[sort].localeCompare(b[sort]);
      }
      // For numbers (year), simple subtraction works
      return sortOrder * (a[sort] - b[sort]);
    });
  }

  // Return the filtered/sorted results wrapped in our standard response format
  res.json({
    success: true,
    data: result
  });
}));

// ============================================================================
// GET /books/:id — Get a Single Book by ID
// ============================================================================

/**
 * @route   GET /books/:id
 * @desc    Retrieve a single book by its numeric ID
 * @access  Public
 *
 * URL PARAMETER:
 *   - id (number) : The unique identifier of the book
 *
 * RESPONSE EXAMPLE (GET /books/1):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "To Kill a Mockingbird",
 *     "author": "Harper Lee",
 *     "genre": "Fiction",
 *     "year": 1960,
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T10:30:00.000Z"
 *   }
 * }
 */
router.get(
  '/:id',
  // Validate that :id is a positive integer BEFORE running the handler
  validateId('params', 'id'),
  asyncHandler(async (req, res) => {
    // req.id was set by the validateId middleware above
    const book = getBookById(req.id);

    // If not found, throw our custom NotFoundError — it will be caught by errorHandler
    if (!book) {
      throw new NotFoundError('Book');
    }

    res.json({
      success: true,
      data: book
    });
  })
);

// ============================================================================
// POST /books — Create a New Book
// ============================================================================

/**
 * @route   POST /books
 * @desc    Create a new book record
 * @access  Public
 *
 * REQUEST BODY (JSON):
 * {
 *   "title": "The Catcher in the Rye",
 *   "author": "J.D. Salinger",
 *   "genre": "Fiction",
 *   "year": 1951
 * }
 *
 * All four fields are required. The validateBody middleware enforces this.
 *
 * RESPONSE EXAMPLE (201 Created):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 6,
 *     "title": "The Catcher in the Rye",
 *     "author": "J.D. Salinger",
 *     "genre": "Fiction",
 *     "year": 1951,
 *     "createdAt": "2024-01-15T12:00:00.000Z",
 *     "updatedAt": "2024-01-15T12:00:00.000Z"
 *   }
 * }
 */
router.post(
  '/',
  // Validate that title, author, genre, and year are present in the request body
  validateBody('title', 'author', 'genre', 'year'),
  asyncHandler(async (req, res) => {
    const { title, author, genre, year } = req.body;

    /**
     * ADDITIONAL VALIDATION:
     * Beyond checking presence, we validate types and value ranges.
     * This prevents invalid data like year: "abc" or year: -500 from entering the store.
     */

    // Validate year is a reasonable integer (published between 1000 AD and current year + 1)
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 1000 || year > currentYear + 1) {
      throw new ValidationError(
        `Invalid year: must be an integer between 1000 and ${currentYear + 1}`
      );
    }

    // Create the book in our data store — it auto-assigns id, createdAt, updatedAt
    const newBook = createBook({ title, author, genre, year });

    /**
     * HTTP STATUS CODE: 201 Created
     * Per REST conventions, POST requests that create a resource should return 201
     * (not 200 OK) to indicate that a new resource was successfully created.
     */
    res.status(201).json({
      success: true,
      data: newBook
    });
  })
);

// ============================================================================
// PUT /books/:id — Update an Existing Book
// ============================================================================

/**
 * @route   PUT /books/:id
 * @desc    Fully update an existing book by ID
 * @access  Public
 *
 * URL PARAMETER:
 *   - id (number) : The unique identifier of the book to update
 *
 * REQUEST BODY (JSON) — all fields required for full replacement:
 * {
 *   "title": "Updated Title",
 *   "author": "Updated Author",
 *   "genre": "Updated Genre",
 *   "year": 2024
 * }
 *
 * NOTE: We use PUT (not PATCH) because this handler requires ALL fields.
 * In a production app, you might also add a PATCH route for partial updates.
 *
 * RESPONSE EXAMPLE (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "Updated Title",
 *     "author": "Harper Lee",
 *     "genre": "Fiction",
 *     "year": 1960,
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T14:00:00.000Z"
 *   }
 * }
 */
router.put(
  '/:id',
  validateId('params', 'id'),
  validateBody('title', 'author', 'genre', 'year'),
  asyncHandler(async (req, res) => {
    const { id } = req.params;
    const { title, author, genre, year } = req.body;

    // Check if the book exists before attempting update
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book');
    }

    // Validate year range (same logic as POST)
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 1000 || year > currentYear + 1) {
      throw new ValidationError(
        `Invalid year: must be an integer between 1000 and ${currentYear + 1}`
      );
    }

    // Perform the update in our data store
    const updatedBook = updateBook(id, { title, author, genre, year });

    res.json({
      success: true,
      data: updatedBook
    });
  })
);

// ============================================================================
// DELETE /books/:id — Delete a Book
// ============================================================================

/**
 * @route   DELETE /books/:id
 * @desc    Delete a book by its numeric ID
 * @access  Public
 *
 * URL PARAMETER:
 *   - id (number) : The unique identifier of the book to delete
 *
 * RESPONSE EXAMPLE (200 OK):
 * {
 *   "success": true,
 *   "message": "Book with id 3 deleted successfully"
 * }
 *
 * NOTE: We return 200 (not 204 No Content) because we include a confirmation
 * message in the response body. Some APIs prefer 204 with an empty body for
 * DELETE operations — both are valid REST conventions.
 */
router.delete(
  '/:id',
  validateId('params', 'id'),
  asyncHandler(async (req, res) => {
    const { id } = req.params;

    // Attempt to delete the book
    const deleted = deleteBook(id);

    if (!deleted) {
      throw new NotFoundError('Book');
    }

    res.json({
      success: true,
      message: `Book with id ${id} deleted successfully`
    });
  })
);

// ============================================================================
// Module Export — attach this router to the main app in app.js
// ============================================================================
module.exports = router;
