## File 5: `src/app.js` — Main Application Entry Point

```javascript
/**
 * ============================================================================
 * MAIN APPLICATION — Express Server Setup
 * ============================================================================
 *
 * DESIGN RATIONALE:
 * This is the entry point of our application. It wires together Express, our
 * routes, and middleware in the correct order. The order matters significantly
 * in Express because middleware executes top-to-bottom like a pipeline.
 *
 * MIDDLEWARE ORDER (critical!):
 * 1. Body parsing middleware — must come FIRST so req.body is available to routes
 * 2. Book routes — our application logic
 * 3. Stats route — also part of books router (mounted at /stats sub-path)
 * 4. notFoundHandler — catches requests that didn't match any route above
 * 5. errorHandler — catches ALL errors from the pipeline above
 *
 * If you swap steps 4 and 5, error handling won't work for 404s.
 * If you put routes after errorHandler, they'll never execute.
 */

const express = require('express');

// Import our route modules and middleware
const bookRoutes = require('./routes/books');
const { errorHandler, notFoundHandler } = require('./middleware/errorHandler');

// Create the Express application instance
const app = express();

// ============================================================================
// Middleware Registration
// ============================================================================

/**
 * express.json() — Parses incoming request bodies with JSON payloads.
 * After this middleware runs, req.body will contain the parsed JSON object.
 * Without it, req.body would be undefined for POST/PUT requests.
 * limit: '10kb' prevents abnormally large payloads (DoS protection).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * express.urlencoded() — Parses URL-encoded bodies (form submissions).
 * extended: true uses the qs library for richer object support.
 * We include this even though our API primarily uses JSON, because it's good practice.
 */
app.use(express.urlencoded({ extended: true }));

// ============================================================================
// Route Mounting
// ============================================================================

/**
 * MOUNTING PATTERN:
 * We mount the bookRoutes router at '/books', which means all routes defined
 * in books.js automatically get the /books prefix. For example, router.get('/')
 * becomes GET /books in the full application.
 *
 * This is cleaner than prefixing every route path manually and makes it easy
 * to reorganize or version APIs (e.g., /api/v1/books).
 */
app.use('/books', bookRoutes);

// ============================================================================
// Health Check Endpoint
// ============================================================================

/**
 * @route   GET /health
 * @desc    Simple health check endpoint for monitoring and load balancers
 * @access  Public
 *
 * This is useful for:
 * - Kubernetes liveness probes
 * - Load balancer health checks
 * - Quick manual verification that the server is running
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime() // Seconds since the process started
  });
});

// ============================================================================
// Error Handling Middleware (MUST be last — acts as catch-all)
// ============================================================================

/**
 * Register notFoundHandler BEFORE errorHandler so that 404s are properly
 * converted into NotFoundError objects before the error handler catches them.
 */
app.use(notFoundHandler);
app.use(errorHandler);

// ============================================================================
// Server Startup
// ============================================================================

/**
 * PORT CONFIGURATION:
 * We check for a PORT environment variable (useful in cloud deployments like
 * Heroku, which sets PORT dynamically). If not set, we default to 3000.
 * This is the standard Node.js pattern for configurable ports.
 */
const PORT = process.env.PORT || 3000;

/**
 * Start the HTTP server and log a startup message.
 * The callback fires only after the server is actually listening.
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API Server Running`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Port:        ${PORT}`);
  console.log(`  Base URL:    http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nTest the API with these commands:`);
  console.log(`  curl http://localhost:${PORT}/books`);
  console.log(`  curl -X POST http://localhost:${PORT}/books \\`);
  console.log(`    -H "Content-Type: application/json" \\`);
  console.log(`    -d '{"title":"Test Book","author":"Author","genre":"Genre","year":2024}'`);
  console.log(`\nFull documentation in README.md\n`);
});

// ============================================================================
// Graceful Shutdown — clean up on process termination
// ============================================================================

/**
 * Handle SIGTERM and SIGINT signals for graceful shutdown.
 * This ensures the server stops accepting new connections and finishes
 * any in-flight requests before exiting.
 */
process.on('SIGTERM', () => {
  console.log('\nSIGTERM received. Shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received. Shutting down gracefully...');
  process.exit(0);
});

// Export the app for testing (e.g., Supertest in a test suite)
module.exports = app;
```

