## Arquivo 2: `src/errors/AppError.js`

```javascript
/**
 * Classe base para erros personalizados da aplicação.
 *
 * POR QUE UMA CLASSE DE ERRO PERSONALIZADA?
 * ------------------------------------------
 * Erros nativos do JavaScript (Error, TypeError, etc.) não carregam
 * informações estruturadas como código de status HTTP e tipo de erro.
 * Uma classe personalizada nos permite:
 *   1. Injetar o statusCode diretamente no construtor
 *   2. Manter uma propriedade `isOperational` para distinguir erros
 *      previsíveis (ex: recurso não encontrado) de bugs inesperados
 *   3. Centralizar o tratamento em um único middleware
 *
 * O padrão "operational error" é amplamente adotado em APIs profissionais
 * (ex: Node.js Enterprise API Templates) para separar erros de negócio
 * de erros de infraestrutura.
 */
class AppError extends Error {
  /**
   * @param {string} message - Descrição legível do erro
   * @param {number} statusCode - Código HTTP correspondente (padrão: 500)
   * @param {string} [errorCode] - Identificador programático do erro (ex: "BOOK_NOT_FOUND")
   */
  constructor(message, statusCode = 500, errorCode = 'INTERNAL_ERROR') {
    // Chama o construtor da classe base Error, passando a mensagem.
    // Isso garante que .message e .stack sejam populados corretamente.
    super(message);

    // Atributos personalizados da classe AppError:
    this.statusCode = statusCode;   // Código HTTP retornado ao cliente
    this.errorCode = errorCode;     // Identificador para logging/monitoramento
    this.isOperational = true;      // Indica que é um erro esperado, não um bug

    // Captura o stack trace no ponto de criação do erro (melhor precisão
    // que o padrão do Error, que pode capturar no throw).
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Subclasse para erros de validação (422 Unprocessable Entity).
 *
 * POR QUE UMA SUBCLASSE?
 * -----------------------
 * Erros de validação têm semântica diferente de outros erros: o cliente
 * enviou dados malformados, não houve falha no servidor. Uma subclasse
 * permite tratamento diferenciado e mensagens mais específicas.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Descrição do erro de validação
   * @param {Object} [details] - Detalhes estruturados dos campos inválidos
   */
  constructor(message, details = {}) {
    super(message, 422, 'VALIDATION_ERROR');
    this.details = details; // Ex: { title: 'é obrigatório', author: 'muito curto' }
  }
}

/**
 * Subclasse para erros de recurso não encontrado (404 Not Found).
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    super(`${resource} com ID ${id} não encontrado`, 404, 'NOT_FOUND');
    this.resource = resource;
    this.id = id;
  }
}

module.exports = { AppError, ValidationError, NotFoundError };
```

