## Arquivo 3: `src/data/store.js`

```javascript
/**
 * Armazenamento em memória para a API de livros.
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * --------------------------
 * Para um exemplo educacional, um array em memória é a escolha ideal porque:
 *   1. Não requer instalação de banco de dados (zero configuração)
 *   2. Operações são O(1) para push/pop e O(n) para busca — suficiente para
 *      demonstrar CRUD sem complexidade desnecessária
 *   3. Facilita o entendimento do fluxo de dados: cada operação é transparente
 *
 * POR QUE NÃO USAR UM OBJETO { id: livro }?
 * ------------------------------------------
 * Um objeto mapeando ID → livro daria busca O(1), mas:
 *   - Listagem exigiria Object.values() (menos intuitivo)
 *   - A API REST padrão usa arrays para coleções
 *   - Para fins educacionais, a simplicidade do array vence
 *
 * IMPORTANTE: Em produção, substitua este módulo por um repositório que
 * use MongoDB, PostgreSQL, etc. Este arquivo é uma abstração intencional.
 */

// Array principal que armazena todos os livros.
// Inicializamos com dados de seed para facilitar testes imediatos.
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
    createdAt: new Date('2024-01-15T10:00:00Z'),
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
    createdAt: new Date('2024-01-16T14:30:00Z'),
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
    createdAt: new Date('2024-02-01T09:00:00Z'),
  },
];

/**
 * Gera um ID único baseado no timestamp atual.
 *
 * POR QUE TIMESTAMP?
 * ------------------
 * Para uma API educacional, `Date.now()` é suficiente e evita a necessidade
 * de bibliotecas como UUID. Em produção, use crypto.randomUUID() ou uma
 * sequência do banco de dados para garantir unicidade global.
 */
function generateId() {
  return Date.now();
}

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista de objetos livro
 */
function findAll() {
  return [...books]; // Retorna cópia para evitar mutação externa do array interno
}

/**
 * Busca um livro pelo ID.
 * @param {number|string} id - ID do livro
 * @returns {Object|null} Livro encontrado ou null
 */
function findById(id) {
  return books.find((book) => book.id === Number(id)) || null;
}

/**
 * Adiciona um novo livro ao armazenamento.
 * @param {Object} bookData - Dados do livro (sem id)
 * @returns {Object} Livro criado com ID atribuído
 */
function create(bookData) {
  const newBook = {
    ...bookData, // Espalha os dados fornecidos pelo cliente
    id: generateId(), // Atribui ID único
    createdAt: new Date().toISOString(), // Registra data de criação em ISO 8601
  };
  books.push(newBook); // Adiciona ao final do array (O(1))
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 * @param {number|string} id - ID do livro a atualizar
 * @param {Object} updates - Campos a atualizar (partial update)
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === Number(id));
  if (index === -1) return null;

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // Usamos Object.assign para mesclar: o livro existente recebe os novos valores
  // nos campos especificados, mantendo os demais inalterados.
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Remove um livro pelo ID.
 * @param {number|string} id - ID do livro a remover
 * @returns {boolean} True se removido, false se não encontrado
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === Number(id));
  if (index === -1) return false;

  // splice retorna um array com o elemento removido; desestruturamos para obter o livro
  const [removed] = books.splice(index, 1);
  return removed !== undefined;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * POR QUE CÁLCULO NO STORE E NÃO NO ROUTE?
 * -----------------------------------------
 * Separamos a lógica de negócio (estatísticas) da camada de apresentação (rotas).
 * Isso permite reutilizar as estatísticas em outros contextos (ex: job em background,
 * WebSocket broadcast) sem duplicar código.
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para agregação
  const byGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Livro mais antigo e mais recente por data de criação
  const oldest = books.length > 0 ? new Date(Math.min(...books.map((b) => b.createdAt))) : null;
  const newest = books.length > 0 ? new Date(Math.max(...books.map((b) => b.createdAt))) : null;

  // Ano médio de publicação (arredondado)
  const avgYear =
    total > 0 ? Math.round(books.reduce((sum, b) => sum + b.year, 0) / total) : null;

  return { total, byGenre, oldestPublication: oldest, newestPublication: newest, averageYear: avgYear };
}

module.exports = { findAll, findById, create, update, remove, getStats };
```

