## Arquivo 4: `src/middleware/errorHandler.js`

```javascript
/**
 * Middleware de tratamento de erros centralizado.
 *
 * POR QUE UM MIDDLEWARE DE ERROS?
 * --------------------------------
 * Express possui um mecanismo especial para middlewares de erro: funções com
 * 4 parâmetros (err, req, res, next). Isso permite capturar erros de qualquer
 * rota e formatar a resposta de forma consistente, sem repetir código de
 * response em cada handler.
 *
 * O padrão segue a convenção do Express: se um erro é passado para next(err),
 * o fluxo pula diretamente para este middleware, ignorando middlewares
 * intermediários não-error.
 */

const { AppError } = require('../errors/AppError');

/**
 * Middleware que captura e trata todos os erros da aplicação.
 *
 * @param {Error} err - Erro capturado (pode ser AppError ou Error nativo)
 * @param {import('express').Request} req - Objeto request do Express
 * @param {import('express').Response} res - Objeto response do Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Log do erro no servidor para fins de depuração e monitoramento.
  // Em produção, envie para um serviço como Sentry ou ELK Stack.
  console.error(`[ERROR] ${new Date().toISOString()} |`, err);

  // Se for um AppError personalizado, usamos seus atributos estruturados.
  // Isso garante que erros de negócio (404, 422) tenham respostas limpas.
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      errorCode: err.errorCode,
      message: err.message,
      // Inclui detalhes de validação apenas se existirem (evita ruído em outros erros)
      ...(err.details && { details: err.details }),
    });
  }

  // Para erros não tratados (bugs do servidor), retornamos 500 genérico.
  // NÃO expomos o stack trace ao cliente por segurança (vazamento de info interna).
  return res.status(500).json({
    success: false,
    errorCode: 'INTERNAL_ERROR',
    message: 'Erro interno do servidor. Tente novamente mais tarde.',
  });
}

module.exports = { errorHandler };
```

