## Arquivo 5: `src/middleware/notFound.js`

```javascript
/**
 * Middleware para requisições a rotas inexistentes (404).
 *
 * POR QUE ESTE MIDDLEWARE?
 * -------------------------
 * Colocado após todas as rotas, este middleware captura qualquer requisição
 * que não foi respondida. Sem ele, o Express retornaria uma página HTML
 * genérica de erro 404, o que quebraria a consistência da API JSON.
 */

/**
 * Middleware que responde com 404 para rotas não encontradas.
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFound(req, res, next) {
  // Usamos AppError para manter a consistência do formato de resposta
  const error = new Error(`Rota ${req.method} ${req.originalUrl} não encontrada`);
  error.statusCode = 404;
  error.errorCode = 'NOT_FOUND';

  // Passamos o erro para o middleware errorHandler (padrão Express)
  next(error);
}

module.exports = { notFound };
```

