## Arquivo 6: `src/routes/books.js`

```javascript
/**
 * Rotas da API de Livros.
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar rotas em arquivos distintos segue o princípio de responsabilidade única:
 *   - index.js configura a aplicação
 *   - routes/books.js define o comportamento de cada endpoint
 * Isso facilita a manutenção, testes unitários e escalabilidade quando a API
 * cresce (ex: adicionar rota /authors em um arquivo separado).
 *
 * POR QUE EXPRESS.Router()?
 * --------------------------
 * O router permite agrupar rotas com prefixo comum (/books) e aplicar
 * middlewares específicos do grupo. É o padrão recomendado pela documentação
 * oficial do Express para APIs modulares.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador isolado

const { findAll, findById, create, update, remove, getStats } = require('../data/store');
const { AppError, ValidationError, NotFoundError } = require('../errors/AppError');

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================

/**
 * @route   GET /books
 * @desc    Retorna lista de livros com suporte a filtragem por query params
 * @access  Public
 *
 * QUERY PARAMS (opcionais):
 *   - author    : Filtra por autor (case-insensitive, substring match)
 *   - genre     : Filtra por gênero
 *   - year      : Filtra por ano exato de publicação
 *   - search    : Busca por título ou autor (substring, case-insensitive)
 *   - sort      : Ordenação — "year_asc", "year_desc", "title_asc", "title_desc"
 *   - page      : Número da página (padrão: 1)
 *   - limit     : Itens por página (padrão: 10, máximo: 100)
 *
 * @example curl "http://localhost:3000/books?genre=Fantasia&sort=year_asc&page=1&limit=5"
 * @example curl "http://localhost:3000/books?search=tolkien"
 */
router.get('/', (req, res) => {
  // Começamos com uma cópia da lista completa para não mutar o store
  let result = findAll();

  // --- FILTRAGEM ---
  const { author, genre, year, search, sort, page = 1, limit = 10 } = req.query;

  // Filtro por autor: converte para minúsculas e verifica se o termo está contido
  if (author) {
    const term = author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(term));
  }

  // Filtro por gênero: correspondência exata (case-insensitive)
  if (genre) {
    const term = genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === term);
  }

  // Filtro por ano: conversão para número e comparação exata
  if (year) {
    const yearNum = Number(year);
    if (isNaN(yearNum)) {
      return res.status(400).json({ success: false, message: 'Parâmetro "year" deve ser um número válido' });
    }
    result = result.filter((book) => book.year === yearNum);
  }

  // Busca livre por título ou autor
  if (search) {
    const term = search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(term) ||
        book.author.toLowerCase().includes(term),
    );
  }

  // --- ORDENAÇÃO ---
  if (sort) {
    const [field, direction] = sort.split('_');
    const multiplier = direction === 'desc' ? -1 : 1;

    result.sort((a, b) => {
      // Suporte a ordenação por "year" e "title"
      if (field === 'year') return (a.year - b.year) * multiplier;
      if (field === 'title') return a.title.localeCompare(b.title) * multiplier;
      // Se campo inválido, ignora a ordenação
      return 0;
    });
  }

  // --- PAGINAÇÃO ---
  const pageNum = Math.max(1, Number(page));
  const limitNum = Math.min(Math.max(1, Number(limit)), 100); // Limita máximo a 100
  const total = result.length;
  const totalPages = Math.ceil(total / limitNum);

  // Slice retorna os itens da página atual (O(k) onde k = limit)
  const paginatedItems = result.slice((pageNum - 1) * limitNum, pageNum * limitNum);

  // Resposta estruturada com metadados de paginação
  return res.json({
    success: true,
    data: paginatedItems,
    pagination: {
      currentPage: pageNum,
      totalPages,
      totalItems: total,
      itemsPerPage: limitNum,
      hasNextPage: pageNum < totalPages,
      hasPrevPage: pageNum > 1,
    },
  });
});

// ============================================================================
// GET /books/stats — Estatísticas agregadas
// ============================================================================

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas sobre o acervo de livros
 * @access  Public
 *
 * @example curl "http://localhost:3000/books/stats"
 * @responseBody {
 *   "success": true,
 *   "data": {
 *     "total": 3,
 *     "byGenre": { "Fantasia": 1, "Distopia": 1, "Romance": 1 },
 *     "oldestPublication": "2024-01-15T10:00:00.000Z",
 *     "newestPublication": "2024-02-01T09:00:00.000Z",
 *     "averageYear": 1967
 *   }
 * }
 */
router.get('/stats', (req, res) => {
  const stats = getStats();
  return res.json({ success: true, data: stats });
});

// ============================================================================
// GET /books/:id — Obter livro por ID
// ============================================================================

/**
 * @route   GET /books/:id
 * @desc    Retorna um livro específico pelo seu ID
 * @access  Public
 *
 * @param {number} id - ID numérico do livro (path parameter)
 *
 * @example curl "http://localhost:3000/books/1"
 * @responseBody {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1954,
 *     "genre": "Fantasia",
 *     "createdAt": "2024-01-15T10:00:00.000Z"
 *   }
 * }
 */
router.get('/:id', (req, res) => {
  const book = findById(req.params.id);

  // Se não encontrado, lançamos NotFoundError que será capturado pelo middleware
  if (!book) {
    throw new NotFoundError('Livro', req.params.id);
  }

  return res.json({ success: true, data: book });
});

// ============================================================================
// POST /books — Criar novo livro
// ============================================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro no acervo
 * @access  Public
 *
 * @bodyparam {string} title - Título do livro (obrigatório, mínimo 2 caracteres)
 * @bodyparam {string} author - Autor do livro (obrigatório)
 * @bodyparam {number} year - Ano de publicação (obrigatório, entre 1000 e ano atual)
 * @bodyparam {string} [genre] - Gênero literário (opcional)
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Distopia"}'
 * @responseBody {
 *   "success": true,
 *   "data": {
 *     "id": 1706123456789,
 *     "title": "Admirável Mundo Novo",
 *     "author": "Aldous Huxley",
 *     "year": 1932,
 *     "genre": "Distopia",
 *     "createdAt": "2024-01-24T15:30:00.000Z"
 *   }
 * }
 */
router.post('/', (req, res) => {
  const { title, author, year, genre } = req.body;

  // --- VALIDAÇÃO DOS CAMPOS OBRIGATÓRIOS ---
  const errors = {};

  if (!title || typeof title !== 'string' || title.trim().length < 2) {
    errors.title = 'Título é obrigatório e deve ter pelo menos 2 caracteres';
  }
  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    errors.author = 'Autor é obrigatório';
  }
  if (year === undefined || year === null) {
    errors.year = 'Ano de publicação é obrigatório';
  } else {
    const yearNum = Number(year);
    const currentYear = new Date().getFullYear();
    if (isNaN(yearNum) || yearNum < 1000 || yearNum > currentYear + 1) {
      errors.year = `Ano deve ser um número entre 1000 e ${currentYear + 1}`;
    }
  }
  if (genre !== undefined && (typeof genre !== 'string' || genre.trim().length === 0)) {
    errors.genre = 'Gênero, se fornecido, deve ser uma string não vazia';
  }

  // Se houver erros de validação, lançamos ValidationError com os detalhes
  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Validação falhou', errors);
  }

  // Cria o livro no store e retorna com status 201 (Created)
  const newBook = create({ title: title.trim(), author: author.trim(), year: Number(year), genre: genre ? genre.trim() : undefined });
  return res.status(201).json({ success: true, data: newBook });
});

// ============================================================================
// PUT /books/:id — Atualizar livro existente (full update)
// ============================================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 *
 * NOTA: PUT implica full update — todos os campos obrigatórios devem ser enviados.
 * Para partial update, use PATCH (não implementado neste exemplo).
 *
 * @param {number} id - ID do livro a atualizar
 * @bodyparam {string} title - Título do livro
 * @bodyparam {string} author - Autor do livro
 * @bodyparam {number} year - Ano de publicação
 * @bodyparam {string} [genre] - Gênero literário
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis - Edição Ilustrada","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 * @responseBody {
 *   "success": true,
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis - Edição Ilustrada",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1954,
 *     "genre": "Fantasia",
 *     "createdAt": "2024-01-15T10:00:00.000Z"
 *   }
 * }
 */
router.put('/:id', (req, res) => {
  const book = findById(req.params.id);

  // Verifica se o livro existe antes de tentar atualizar
  if (!book) {
    throw new NotFoundError('Livro', req.params.id);
  }

  const { title, author, year, genre } = req.body;
  const errors = {};

  // Reutilizamos a mesma lógica de validação do POST
  if (!title || typeof title !== 'string' || title.trim().length < 2) {
    errors.title = 'Título é obrigatório e deve ter pelo menos 2 caracteres';
  }
  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    errors.author = 'Autor é obrigatório';
  }
  if (year === undefined || year === null) {
    errors.year = 'Ano de publicação é obrigatório';
  } else {
    const yearNum = Number(year);
    const currentYear = new Date().getFullYear();
    if (isNaN(yearNum) || yearNum < 1000 || yearNum > currentYear + 1) {
      errors.year = `Ano deve ser um número entre 1000 e ${currentYear + 1}`;
    }
  }

  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Validação falhou', errors);
  }

  // Atualiza o livro no store
  const updatedBook = update(req.params.id, {
    title: title.trim(),
    author: author.trim(),
    year: Number(year),
    genre: genre ? genre.trim() : undefined,
  });

  return res.json({ success: true, data: updatedBook });
});

// ============================================================================
// DELETE /books/:id — Excluir livro
// ============================================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do acervo
 * @access  Public
 *
 * @param {number} id - ID do livro a excluir
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 * @responseBody {
 *   "success": true,
 *   "message": "Livro com ID 1 excluído com sucesso"
 * }
 */
router.delete('/:id', (req, res) => {
  const book = findById(req.params.id);

  if (!book) {
    throw new NotFoundError('Livro', req.params.id);
  }

  // Remove o livro e verifica se a operação foi bem-sucedida
  const removed = remove(req.params.id);
  if (!removed) {
    // Caso teórico: findById encontrou mas remove falhou (concorrência extrema)
    throw new AppError('Falha ao excluir o livro', 500, 'DELETE_FAILED');
  }

  // 200 OK com mensagem de confirmação — padrão REST para DELETE bem-sucedido
  return res.json({ success: true, message: `Livro com ID ${req.params.id} excluído com sucesso` });
});

module.exports = router;
```

