## Arquivo 7: `src/app.js`

```javascript
/**
 * Configuração da aplicação Express.
 *
 * POR QUE ARQUIVO SEPARADO?
 * --------------------------
 * Separar a configuração do Express (app.js) do ponto de entrada (index.js)
 * permite testar a aplicação sem iniciar o servidor HTTP, e mantém a
 * responsabilidade de "como configurar" distinta de "quando iniciar".
 */

const express = require('express');
const booksRouter = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');
const { notFound } = require('./middleware/notFound');

const app = express();

// ============================================================================
// Middleware Global
// ============================================================================

/**
 * express.json() — Parser de body JSON.
 *
 * POR QUE ESTE MIDDLEWARE?
 * -------------------------
 * Express não parseia o body automaticamente. Sem este middleware, req.body
 * seria undefined em requisições POST/PUT. É um dos middlewares mais
 * fundamentais para APIs REST que recebem dados JSON.
 */
app.use(express.json());

/**
 * express.urlencoded() — Parser de formulários codificados.
 *
 * Mantemos habilitado com extended: true para suportar objetos aninhados
 * em bodies do tipo application/x-www-form-urlencoded, caso necessário.
 */
app.use(express.urlencoded({ extended: true }));

// ============================================================================
// Rotas
// ============================================================================

/**
 * Rota raiz — Health check da API.
 * Útil para monitoramento (kubernetes liveness probe) e testes rápidos.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando!',
    endpoints: {
      docs: 'Veja o README.md para exemplos de uso',
      books: '/books',
      stats: '/books/stats',
    },
  });
});

/**
 * Mount do router de livros no prefixo /books.
 *
 * POR QUE MOUNT?
 * --------------
 * app.use('/books', router) registra todas as rotas do router com o prefixo
 * /books automaticamente. Isso significa que router.get('/') vira GET /books,
 * router.get('/:id') vira GET /books/:id, etc. É a forma canônica do Express
 * de organizar APIs modulares.
 */
app.use('/books', booksRouter);

// ============================================================================
// Middleware de Tratamento de Erros (DEVE ser o último)
// ============================================================================

/**
 * notFound — Captura rotas inexistentes (404).
 * Colocado ANTES do errorHandler para que erros 404 sejam tratados corretamente.
 */
app.use(notFound);

/**
 * errorHandler — Middleware global de tratamento de erros.
 *
 * POR QUE POR ÚLTIMO?
 * --------------------
 * No Express, middlewares são executados em ordem FIFO. O middleware de erro
 * deve ser o último porque:
 *   1. Precisa capturar erros de TODOS os middlewares e rotas anteriores
 *   2. Se colocado antes, interceptaria erros que outros middlewares poderiam
 *      tratar de forma específica
 *
 * A assinatura com 4 parâmetros (err, req, res, next) é o que diferencia
 * um middleware de erro de um middleware normal no Express.
 */
app.use(errorHandler);

module.exports = app;
```

