/**
 * Ponto de entrada da aplicação.
 *
 * POR QUE ESTE PADRÃO?
 * ---------------------
 * index.js é o arquivo que inicia o servidor HTTP e ouve em uma porta.
 * A lógica de configuração fica em app.js (importado), mantendo a separação:
 *   - app.js  → "como a aplicação funciona"
 *   - index.js → "quando e onde iniciar"
 */

const app = require('./app');

// Porta configurável via variável de ambiente, com fallback para 3000.
// Isso permite rodar múltiplas instâncias em portas diferentes (ex: testes paralelos).
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor e faz log de inicialização.
 *
 * POR QUE ARROW FUNCTION NO CALLBACK?
 * ------------------------------------
 * Arrow functions não criam seu próprio `this`, o que evita bugs comuns de
 * escopo em callbacks do Node.js. Para funções simples como esta, são a escolha
 * mais limpa e legível.
 */
app.listen(PORT, () => {
  console.log(`╔══════════════════════════════════════════════════╗`);
